from jsonb_to_recordset($q$[{"id":1400,"materia":"pen","nivel":1,"enunciado":"O crime que exige resultado naturalístico para se consumar é crime:","opcoes":["Material","Formal","De mera conduta","De perigo abstrato"],"explicacao":"Ex.: homicídio, que só se consuma com a morte."},{"id":1401,"materia":"pen","nivel":1,"enunciado":"Pela Súmula 96 do STJ, a extorsão se consuma:","opcoes":["Com o constrangimento, sem precisar da vantagem","Só quando a vantagem é de fato obtida","Só quando o autor é preso em flagrante","Só quando a vítima registra a ocorrência"],"explicacao":"É crime formal."},{"id":1402,"materia":"pen","nivel":1,"enunciado":"Pegar um objeto alheio só para usar e devolvê-lo logo depois intacto é, em regra:","opcoes":["Fato atípico","Furto simples","Furto qualificado","Roubo impróprio"],"explicacao":"É o furto de uso, que não é crime no Código Penal comum."},{"id":1403,"materia":"pen","nivel":1,"enunciado":"O preso que foge usando violência contra a pessoa comete:","opcoes":["Evasão mediante violência","Resistência à prisão","Desacato a funcionário","Dano qualificado ao presídio"],"explicacao":"Art. 352 do Código Penal."},{"id":1404,"materia":"pen","nivel":1,"enunciado":"Promover ou facilitar a fuga de pessoa legalmente presa é crime de:","opcoes":["Fuga de pessoa presa","Favorecimento real","Evasão mediante violência","Resistência"],"explicacao":"Art. 351 do Código Penal."},{"id":1405,"materia":"pen","nivel":1,"enunciado":"O inimputável por doença mental que pratica crime recebe:","opcoes":["Medida de segurança","Pena de prisão comum","Apenas pena de multa","Pena reduzida pela metade"],"explicacao":"Art. 97 do Código Penal."},{"id":1406,"materia":"pen","nivel":1,"enunciado":"Para o semi-imputável (art. 26, parágrafo único), a pena pode ser:","opcoes":["Reduzida de 1/3 a 2/3","Aumentada de 1/3","Substituída por advertência","Extinta automaticamente"],"explicacao":"Ou substituída por medida de segurança (art. 98)."},{"id":1407,"materia":"pen","nivel":1,"enunciado":"Abandonar recém-nascido para ocultar desonra própria é crime de:","opcoes":["Exposição ou abandono de recém-nascido","Abandono de incapaz qualificado","Omissão de socorro a criança","Infanticídio na forma tentada"],"explicacao":"Art. 134 do Código Penal."},{"id":1408,"materia":"ppen","nivel":1,"enunciado":"Quando a polícia descobre o crime em suas atividades de rotina, a notícia do crime é de cognição:","opcoes":["Imediata","Mediata","Coercitiva","Indireta"],"explicacao":"Mediata é por provocação, como uma requisição. Coercitiva é a do flagrante."},{"id":1409,"materia":"ppen","nivel":1,"enunciado":"A delatio criminis é a comunicação do crime feita:","opcoes":["Por qualquer pessoa do povo","Apenas pelo juiz","Apenas pelo Ministério Público","Apenas pelo delegado"],"explicacao":"Art. 5º, § 3º, do CPP."},{"id":1410,"materia":"ppen","nivel":1,"enunciado":"Quando pode ser feito o exame de corpo de delito?","opcoes":["Em qualquer dia e hora","Só em dias úteis","Só durante o dia","Só com ordem judicial"],"explicacao":"Art. 161 do CPP."},{"id":1411,"materia":"ppen","nivel":1,"enunciado":"A testemunha que falta sem motivo justificado pode ser:","opcoes":["Conduzida coercitivamente","Presa preventivamente","Processada por calúnia","Dispensada do depoimento"],"explicacao":"Art. 218 do CPP, além de multa."},{"id":1412,"materia":"ppen","nivel":1,"enunciado":"Em regra, o depoimento da testemunha é prestado:","opcoes":["Oralmente","Por escrito","Por e-mail","Por procurador"],"explicacao":"Art. 204 do CPP. Ela pode consultar breves apontamentos."},{"id":1413,"materia":"ppen","nivel":1,"enunciado":"Quem NÃO presta o compromisso de dizer a verdade, entre outros?","opcoes":["Menores de 14 anos e doentes mentais","Policiais que atuaram no caso","Vizinhos e conhecidos da vítima","Servidores públicos em geral"],"explicacao":"Art. 208 do CPP."},{"id":1414,"materia":"ppen","nivel":1,"enunciado":"Em regra, quem pode atuar como assistente de acusação é:","opcoes":["O ofendido ou seu representante legal","Qualquer pessoa do povo interessada","O delegado que investigou o caso","A Defensoria Pública da União"],"explicacao":"Art. 268 do CPP."},{"id":1415,"materia":"ppen","nivel":1,"enunciado":"O autor de infração de menor potencial ofensivo que se recusa a ir ao juizado:","opcoes":["Pode ter o auto de flagrante lavrado","Nunca pode ser preso em flagrante","É solto sem nenhum tipo de registro","É levado direto ao Conselho Tutelar"],"explicacao":"Art. 69, parágrafo único, da Lei 9.099/1995."},{"id":1416,"materia":"ppen","nivel":1,"enunciado":"A queixa-crime pode ser apresentada por:","opcoes":["Advogado com poderes especiais","Qualquer pessoa do povo","Delegado de polícia da área","Juiz responsável pela causa"],"explicacao":"Art. 44 do CPP."},{"id":1417,"materia":"inf","nivel":1,"enunciado":"Na maioria dos programas, o atalho Ctrl + Y serve para:","opcoes":["Refazer","Desfazer","Imprimir","Salvar"],"explicacao":"Desfazer é Ctrl + Z."},{"id":1418,"materia":"inf","nivel":1,"enunciado":"No navegador, Ctrl + Shift + T serve para:","opcoes":["Reabrir a última aba fechada","Abrir uma nova janela anônima","Fechar todas as abas","Abrir o histórico"],"explicacao":"A janela anônima é Ctrl + Shift + N no Chrome."},{"id":1419,"materia":"inf","nivel":1,"enunciado":"No navegador, Ctrl + T serve para:","opcoes":["Abrir uma nova aba","Fechar a aba atual","Traduzir a página","Imprimir a página"],"explicacao":"No Word em português, Ctrl + T seleciona tudo."},{"id":1420,"materia":"inf","nivel":1,"enunciado":"No Explorador de Arquivos do Windows, a tecla F2 serve para:","opcoes":["Renomear o item selecionado","Excluir o item selecionado","Abrir a ajuda","Atualizar a pasta"],"explicacao":"A ajuda é F1; atualizar é F5."},{"id":1421,"materia":"inf","nivel":1,"enunciado":"A tecla Print Screen serve para:","opcoes":["Capturar a imagem da tela","Imprimir o documento aberto","Bloquear a tela do computador","Aumentar o brilho do monitor"],"explicacao":"A imagem vai para a área de transferência."},{"id":1422,"materia":"inf","nivel":1,"enunciado":"No Excel, a alça de preenchimento serve para:","opcoes":["Copiar ou continuar sequências arrastando","Mudar a cor de fundo da célula ativa","Mesclar várias células selecionadas","Proteger a planilha com uma senha"],"explicacao":"Ex.: arrastar “jan” gera fev, mar, abr…"},{"id":1423,"materia":"inf","nivel":1,"enunciado":"No LibreOffice, o programa de apresentações é o:","opcoes":["Impress","Calc","Writer","Draw"],"explicacao":"Calc é planilha; Writer, texto; Base, banco de dados."},{"id":1424,"materia":"inf","nivel":1,"enunciado":"No LibreOffice, o programa de planilhas é o:","opcoes":["Calc","Writer","Impress","Draw"],"explicacao":"Equivale ao Excel."},{"id":1425,"materia":"inf","nivel":1,"enunciado":"O cadeado na barra de endereço do navegador indica:","opcoes":["Conexão criptografada (HTTPS)","Site totalmente livre de golpes","Página aprovada pelo governo","Download protegido de vírus"],"explicacao":"Golpistas também usam HTTPS. O cadeado não garante que o site seja legítimo."},{"id":1426,"materia":"rl","nivel":1,"enunciado":"Qual o próximo número da sequência 2, 6, 12, 20, 30, …?","opcoes":["42","40","36","44"],"explicacao":"As diferenças crescem de 2 em 2: 4, 6, 8, 10, 12."},{"id":1427,"materia":"rl","nivel":1,"enunciado":"Se 3x + 5 = 20, quanto vale x?","opcoes":["5","15","25/3","4"],"explicacao":"3x = 15, então x = 5."},{"id":1428,"materia":"rl","nivel":1,"enunciado":"Quanto é 20% de 30% de 500?","opcoes":["30","50","150","25"],"explicacao":"30% de 500 = 150; 20% de 150 = 30."},{"id":1429,"materia":"rl","nivel":1,"enunciado":"Pedro tem o dobro da idade de João. Juntos somam 36 anos. Qual a idade de Pedro?","opcoes":["24","12","18","30"],"explicacao":"João tem x e Pedro 2x: 3x = 36, x = 12."},{"id":1430,"materia":"rl","nivel":1,"enunciado":"A média de 3 números é 10. Dois deles são 8 e 9. Qual é o terceiro?","opcoes":["13","10","12","11"],"explicacao":"A soma é 30: 30 − 8 − 9 = 13."},{"id":1431,"materia":"rl","nivel":1,"enunciado":"Nenhum gato é cachorro. Tom é um gato. Logo:","opcoes":["Tom não é cachorro","Tom é cachorro","Algum cachorro é gato","Nada se conclui"],"explicacao":"Se nenhum gato é cachorro, Tom também não é."},{"id":1432,"materia":"rl","nivel":1,"enunciado":"Qual é a negação de “Ana estuda e trabalha”?","opcoes":["Ana não estuda ou não trabalha","Ana não estuda e não trabalha","Ana estuda ou trabalha","Ana trabalha e não estuda"],"explicacao":"De Morgan: ¬(P ∧ Q) = ¬P ∨ ¬Q."},{"id":1433,"materia":"rl","nivel":1,"enunciado":"Quantos minutos há em um dia?","opcoes":["1.440","1.200","720","3.600"],"explicacao":"24 × 60 = 1.440."},{"id":1434,"materia":"rl","nivel":1,"enunciado":"Numa promoção “leve 3, pague 2”, o desconto por unidade é de aproximadamente:","opcoes":["33%","50%","25%","67%"],"explicacao":"Paga 2 de 3: economiza 1/3."},{"id":1435,"materia":"dh","nivel":1,"enunciado":"A Declaração Universal dos Direitos Humanos é um tratado formalmente obrigatório?","opcoes":["Não, foi adotada como resolução","Sim, foi ratificada pelo Congresso","Sim, tem status de emenda","Sim, revoga leis contrárias"],"explicacao":"É uma resolução da Assembleia Geral da ONU, embora tenha grande força moral e costumeira."},{"id":1436,"materia":"dh","nivel":1,"enunciado":"Quem pode apresentar petição à Comissão Interamericana de Direitos Humanos?","opcoes":["Qualquer pessoa, grupo ou ONG reconhecida","Apenas os governos dos Estados-membros","Apenas advogados inscritos na OAB","Apenas a ONU e seus órgãos"],"explicacao":"Art. 44 da Convenção Americana."},{"id":1437,"materia":"dh","nivel":1,"enunciado":"Pela Constituição, o preso será informado de seus direitos, entre eles o de:","opcoes":["Permanecer calado","Escolher o próprio juiz","Não ser algemado nunca","Ficar sem identificação"],"explicacao":"Art. 5º, LXIII."},{"id":1438,"materia":"dh","nivel":1,"enunciado":"Segundo a Constituição, ninguém será levado ou mantido preso quando a lei admitir:","opcoes":["Liberdade provisória, com ou sem fiança","Apenas o pagamento de uma multa","A confissão espontânea do acusado","O perdão expresso da vítima"],"explicacao":"Art. 5º, LXVI."},{"id":1439,"materia":"dh","nivel":1,"enunciado":"Pela Constituição, a pena será cumprida em estabelecimentos distintos conforme:","opcoes":["Natureza do crime, idade e sexo","A renda declarada do condenado","O bairro onde o condenado mora","A religião declarada do condenado"],"explicacao":"Art. 5º, XLVIII."},{"id":1440,"materia":"dh","nivel":1,"enunciado":"A Constituição assegura aos presos o respeito à:","opcoes":["Integridade física e moral","Liberdade de locomoção plena","Remuneração mínima mensal","Escolha do presídio"],"explicacao":"Art. 5º, XLIX."},{"id":1441,"materia":"dh","nivel":1,"enunciado":"“Nenhuma pena passará da pessoa do condenado” expressa o princípio da:","opcoes":["Pessoalidade da pena","Legalidade estrita","Anterioridade penal","Insignificância"],"explicacao":"Art. 5º, XLV. Também é chamado de intranscendência."},{"id":1442,"materia":"dh","nivel":1,"enunciado":"Pela Lei Brasileira de Inclusão, a deficiência envolve impedimento de longo prazo de natureza:","opcoes":["Física, mental, intelectual ou sensorial","Apenas física e visível a olho nu","Apenas temporária, de curto prazo","Apenas econômica ou social"],"explicacao":"Art. 2º da Lei 13.146/2015."},{"id":1443,"materia":"dh","nivel":1,"enunciado":"Pelo Estatuto da Igualdade Racial, a população negra é formada por quem se autodeclara:","opcoes":["Preto ou pardo","Apenas preto","Indígena ou quilombola","Amarelo ou branco"],"explicacao":"Art. 1º, IV, da Lei 12.288/2010, conforme o quesito cor ou raça do IBGE."},{"id":1444,"materia":"leg","nivel":1,"enunciado":"Pelo ECA, guarda, tutela e adoção são formas de:","opcoes":["Colocação em família substituta","Medida socioeducativa em meio aberto","Internação provisória do adolescente","Acolhimento institucional"],"explicacao":"Art. 28 do ECA."},{"id":1445,"materia":"leg","nivel":1,"enunciado":"Pelo ECA, a adoção é medida:","opcoes":["Excepcional e irrevogável","Comum e revogável","Temporária e renovável","Automática e provisória"],"explicacao":"Art. 39 do ECA."},{"id":1446,"materia":"leg","nivel":1,"enunciado":"Na Lei de Drogas, o tráfico praticado por servidor público no exercício da função tem a pena:","opcoes":["Aumentada de 1/6 a 2/3","Reduzida de 1/3 a 1/2","Igual à pena comum","Dobrada em qualquer caso"],"explicacao":"Art. 40, II, da Lei 11.343/2006."},{"id":1447,"materia":"leg","nivel":1,"enunciado":"Pelo Estatuto do Desarmamento, emprestar arma de fogo a terceiro sem autorização é:","opcoes":["Porte ilegal de arma de fogo","Posse irregular de arma de fogo","Omissão de cautela do dono","Disparo de arma de fogo"],"explicacao":"O art. 14 inclui as condutas de emprestar e ceder."},{"id":1448,"materia":"leg","nivel":1,"enunciado":"Deixar arma ao alcance de menor de 18 anos, que dela se apodera, é crime de:","opcoes":["Omissão de cautela","Porte ilegal de arma","Posse irregular de arma","Comércio ilegal de arma"],"explicacao":"Art. 13 do Estatuto do Desarmamento."},{"id":1449,"materia":"leg","nivel":1,"enunciado":"Na Lei Maria da Penha, a mulher só pode renunciar à representação:","opcoes":["Em audiência perante o juiz","Na delegacia, a qualquer momento","Por mensagem ao agressor","Depois da sentença"],"explicacao":"Art. 16, antes do recebimento da denúncia e ouvido o MP."},{"id":1450,"materia":"leg","nivel":1,"enunciado":"Nos casos da Lei Maria da Penha, é proibido aplicar como pena:","opcoes":["Cesta básica ou só multa","Prisão em regime fechado","Prestação de serviços","Medidas protetivas"],"explicacao":"Art. 17 da Lei 11.340/2006."},{"id":1451,"materia":"leg","nivel":1,"enunciado":"Pelo CTB, a permissão para dirigir (CNH provisória) vale por:","opcoes":["1 ano","2 anos","6 meses","5 anos"],"explicacao":"Art. 148, § 2º, do Código de Trânsito."},{"id":1452,"materia":"leg","nivel":1,"enunciado":"A Lei 13.104/2015 incluiu o feminicídio no Código Penal:","opcoes":["Como qualificadora do homicídio","Como contravenção penal","Como crime culposo","Como infração de menor potencial"],"explicacao":"Também o incluiu entre os crimes hediondos. Em 2024, ele virou crime autônomo."},{"id":1453,"materia":"est","nivel":1,"enunciado":"A média de 10 valores é 5. Somando 2 a cada valor, a nova média é:","opcoes":["7","5","10","20"],"explicacao":"A média também sobe 2."},{"id":1454,"materia":"est","nivel":1,"enunciado":"Qual a moda de: azul, verde, azul, vermelho, azul?","opcoes":["Azul","Verde","Vermelho","Não há moda"],"explicacao":"A moda também vale para dados qualitativos."},{"id":1455,"materia":"est","nivel":1,"enunciado":"Para uma variável qualitativa nominal, a medida de tendência central adequada é a:","opcoes":["Moda","Média","Mediana","Variância"],"explicacao":"Não há como somar ou ordenar categorias como cores."},{"id":1456,"materia":"est","nivel":1,"enunciado":"Qual a mediana de 5, 1 e 3?","opcoes":["3","1","5","9"],"explicacao":"Ordenando: 1, 3, 5."},{"id":1457,"materia":"est","nivel":1,"enunciado":"As frequências relativas das classes são 10%, 30% e 60%. Qual a frequência acumulada até a 2ª classe?","opcoes":["40%","30%","70%","100%"],"explicacao":"10% + 30% = 40%."},{"id":1458,"materia":"est","nivel":1,"enunciado":"A amostragem por conveniência é do tipo:","opcoes":["Não probabilística","Aleatória simples","Estratificada","Sistemática"],"explicacao":"Escolhem-se os elementos mais fáceis de alcançar."},{"id":1459,"materia":"est","nivel":1,"enunciado":"Num histograma de frequências relativas, a soma de todas as barras representa:","opcoes":["100% das observações","Metade dos dados","A média do conjunto","A maior classe apenas"],"explicacao":"Cada barra é uma fração do total."},{"id":1460,"materia":"est","nivel":1,"enunciado":"Qual a moda do conjunto 2, 2, 3, 3?","opcoes":["Duas: 2 e 3","Uma só: 3","Nenhuma","Uma só: 2,5"],"explicacao":"É um conjunto bimodal."},{"id":1461,"materia":"est","nivel":1,"enunciado":"Num baralho comum de 52 cartas, qual a probabilidade de tirar uma carta vermelha?","opcoes":["1/2","1/4","1/13","1/52"],"explicacao":"São 26 vermelhas em 52."},{"id":1462,"materia":"cont","nivel":1,"enunciado":"Pelas partidas dobradas, a soma dos débitos é sempre igual à soma dos:","opcoes":["Créditos","Ativos","Lucros","Estoques"],"explicacao":"Todo débito tem um crédito de igual valor."},{"id":1463,"materia":"cont","nivel":1,"enunciado":"O fato contábil que altera o patrimônio líquido é o:","opcoes":["Modificativo","Permutativo","Neutro","Compensado"],"explicacao":"O permutativo só troca valores e não altera o PL."},{"id":1464,"materia":"cont","nivel":1,"enunciado":"O pagamento de salários já registrados como “salários a pagar”:","opcoes":["Reduz o caixa e os salários a pagar","Gera uma nova despesa no mês do pagamento","Aumenta o patrimônio líquido da empresa","Aumenta o passivo circulante em dobro"],"explicacao":"A despesa já foi reconhecida antes. Agora só se quita a obrigação."},{"id":1465,"materia":"cont","nivel":1,"enunciado":"A compra de material de escritório a prazo, para estoque:","opcoes":["Aumenta o ativo e o passivo","Reduz o ativo e o passivo","Gera receita no período","Reduz o patrimônio líquido"],"explicacao":"Entra o material e surge a dívida com o fornecedor."},{"id":1466,"materia":"cont","nivel":1,"enunciado":"No Balanço Patrimonial, o ativo é apresentado em ordem decrescente de:","opcoes":["Liquidez","Exigibilidade","Valor","Antiguidade"],"explicacao":"Art. 178 da Lei 6.404/1976."},{"id":1467,"materia":"cont","nivel":1,"enunciado":"No Balanço Patrimonial, o passivo é apresentado em ordem decrescente de:","opcoes":["Exigibilidade","Liquidez","Valor contábil","Antiguidade"],"explicacao":"Primeiro o que vence antes."},{"id":1468,"materia":"cont","nivel":1,"enunciado":"O capital próprio de uma empresa corresponde ao:","opcoes":["Patrimônio líquido","Passivo exigível","Ativo total da empresa","Saldo de caixa e bancos"],"explicacao":"O capital de terceiros é o passivo exigível."},{"id":1469,"materia":"cont","nivel":1,"enunciado":"O capital de terceiros corresponde ao:","opcoes":["Passivo exigível","Patrimônio líquido","Ativo circulante","Capital social"],"explicacao":"São recursos de credores, como bancos e fornecedores."},{"id":1470,"materia":"cont","nivel":1,"enunciado":"O lucro bruto é calculado como:","opcoes":["Receita líquida menos CMV","Receita bruta menos impostos","Lucro líquido mais despesas","Ativo menos passivo"],"explicacao":"Depois, subtraem-se as despesas operacionais."},{"id":1471,"materia":"civ","nivel":1,"enunciado":"Bens que podem ser substituídos por outros da mesma espécie, qualidade e quantidade são:","opcoes":["Fungíveis","Infungíveis","Imóveis","Públicos"],"explicacao":"Art. 85 do Código Civil. Ex.: dinheiro, sacas de café."},{"id":1472,"materia":"civ","nivel":1,"enunciado":"Bens cujo uso importa destruição imediata da própria substância são:","opcoes":["Consumíveis","Inconsumíveis","Infungíveis","Imóveis"],"explicacao":"Art. 86. Ex.: alimentos."},{"id":1473,"materia":"civ","nivel":1,"enunciado":"Praças, ruas e praias são bens públicos:","opcoes":["De uso comum do povo","De uso especial do órgão","Dominicais ou disponíveis","Privados de uso coletivo"],"explicacao":"Art. 99, I, do Código Civil."},{"id":1474,"materia":"civ","nivel":1,"enunciado":"Prédios onde funcionam repartições públicas são bens públicos:","opcoes":["De uso especial","De uso comum do povo","Dominicais","Particulares"],"explicacao":"Art. 99, II, do Código Civil."},{"id":1475,"materia":"civ","nivel":1,"enunciado":"Os bens públicos dominicais podem ser:","opcoes":["Alienados, conforme a lei","Adquiridos por usucapião comum","Penhorados por qualquer credor","Doados sem nenhuma formalidade"],"explicacao":"Art. 101 do Código Civil."},{"id":1476,"materia":"civ","nivel":1,"enunciado":"Frutos, produtos e benfeitorias são bens:","opcoes":["Acessórios","Principais","Públicos","Fungíveis"],"explicacao":"Existem em função do bem principal."},{"id":1477,"materia":"civ","nivel":1,"enunciado":"A benfeitoria que conserva a coisa ou evita que ela se deteriore é:","opcoes":["Necessária","Útil","Voluptuária","Acessória"],"explicacao":"Art. 96, § 3º, do Código Civil."},{"id":1478,"materia":"civ","nivel":1,"enunciado":"A benfeitoria de mero deleite ou recreio, como um chafariz decorativo, é:","opcoes":["Voluptuária","Útil","Necessária","Fungível"],"explicacao":"Art. 96, § 1º. Não aumenta o uso habitual do bem."},{"id":1479,"materia":"civ","nivel":1,"enunciado":"Qual destas é pessoa jurídica de direito privado?","opcoes":["Associação de moradores","A União Federal","Uma autarquia federal","Um município do interior"],"explicacao":"Art. 44 do Código Civil."},{"id":1480,"materia":"civ","nivel":1,"enunciado":"Pelo Código Civil, o nome da pessoa compreende:","opcoes":["Prenome e sobrenome","Apenas o prenome","Apelido e prenome","Apenas o sobrenome"],"explicacao":"Art. 16 do Código Civil."},{"id":1481,"materia":"civ","nivel":1,"enunciado":"Em regra, os direitos da personalidade são:","opcoes":["Intransmissíveis e irrenunciáveis","Transmissíveis por herança aos filhos","Renunciáveis por contrato particular","Válidos só para os maiores de idade"],"explicacao":"Art. 11 do Código Civil."},{"id":1482,"materia":"civ","nivel":1,"enunciado":"A obrigação de entregar um carro específico, de placa definida, é obrigação de:","opcoes":["Dar coisa certa","Fazer","Não fazer","Dar coisa incerta"],"explicacao":"A coisa é individualizada desde o início."},{"id":1483,"materia":"civ","nivel":1,"enunciado":"A obrigação de um artista de pintar um quadro é obrigação de:","opcoes":["Fazer","Dar coisa certa","Não fazer","Dar coisa incerta"],"explicacao":"O que se deve é uma atividade."},{"id":1484,"materia":"civ","nivel":1,"enunciado":"O contrato em que só uma parte assume obrigações, como a doação pura, é:","opcoes":["Unilateral","Bilateral","Oneroso","Comutativo"],"explicacao":"Na doação pura, só o doador se obriga."},{"id":1485,"materia":"civ","nivel":1,"enunciado":"Em regra, o contrato de compra e venda é:","opcoes":["Bilateral e oneroso","Unilateral e gratuito","Bilateral e gratuito","Unilateral e oneroso"],"explicacao":"As duas partes têm obrigações e vantagens."},{"id":1486,"materia":"civ","nivel":1,"enunciado":"Emprestar de graça uma coisa infungível, que deve ser devolvida, é o contrato de:","opcoes":["Comodato","Mútuo","Locação","Depósito"],"explicacao":"Art. 579. Ex.: emprestar um carro a um amigo."},{"id":1487,"materia":"civ","nivel":1,"enunciado":"O empréstimo de dinheiro, coisa fungível, é o contrato de:","opcoes":["Mútuo","Comodato","Fiança","Doação"],"explicacao":"Art. 586. Devolve-se coisa do mesmo gênero e quantidade."},{"id":1488,"materia":"civ","nivel":1,"enunciado":"Pelo Código Civil, a união estável é reconhecida como:","opcoes":["Entidade familiar","Contrato de sociedade","Relação sem efeitos jurídicos","Forma de adoção"],"explicacao":"Art. 1.723 do Código Civil."},{"id":1489,"materia":"pciv","nivel":1,"enunciado":"Ao decidir, o juiz deve:","opcoes":["Fundamentar a decisão","Manter a decisão em sigilo","Pedir aval ao tribunal","Consultar as partes antes"],"explicacao":"Art. 11 do CPC e art. 93, IX, da Constituição."},{"id":1490,"materia":"pciv","nivel":1,"enunciado":"O CPC estimula, sempre que possível, a solução consensual por meio de:","opcoes":["Conciliação e mediação","Sorteio entre as partes","Votação popular","Decisão do delegado"],"explicacao":"Art. 3º, § 3º, do CPC."},{"id":1491,"materia":"pciv","nivel":1,"enunciado":"O ato do juiz sem conteúdo decisório, que só impulsiona o processo, é o:","opcoes":["Despacho","Acórdão","Sentença","Recurso"],"explicacao":"Art. 203, § 3º, do CPC."},{"id":1492,"materia":"pciv","nivel":1,"enunciado":"A decisão interlocutória é:","opcoes":["Pronunciamento decisório que não é sentença","Decisão final de um tribunal superior do país","Ato do juiz que apenas impulsiona o processo","Pedido feito pelo autor diretamente ao juiz"],"explicacao":"Art. 203, § 2º, do CPC."},{"id":1493,"materia":"pciv","nivel":1,"enunciado":"O ato que dá ciência a alguém dos atos e termos do processo é a:","opcoes":["Intimação","Citação","Sentença","Notificação extrajudicial"],"explicacao":"Art. 269. A citação é a convocação do réu para integrar o processo."},{"id":1494,"materia":"pciv","nivel":1,"enunciado":"Em regra, o juiz pode decidir contra uma parte sem ouvi-la antes?","opcoes":["Não, salvo exceções como a urgência","Sim, sempre que achar conveniente","Sim, se a causa for de pequeno valor","Sim, sempre que o autor pedir"],"explicacao":"Art. 9º do CPC."},{"id":1495,"materia":"pciv","nivel":1,"enunciado":"A petição inicial deve indicar, entre outros requisitos:","opcoes":["O valor da causa","O nome do juiz","A sentença desejada","O telefone do réu"],"explicacao":"Art. 319 do CPC."},{"id":1496,"materia":"pciv","nivel":1,"enunciado":"Se a petição inicial tiver um defeito que pode ser corrigido, o juiz deve:","opcoes":["Mandar emendá-la em 15 dias","Extinguir o processo na hora","Condenar o autor em multa","Arquivar sem avisar"],"explicacao":"Art. 321 do CPC."},{"id":1497,"materia":"pciv","nivel":1,"enunciado":"Em regra, quem deve provar o fato constitutivo do direito é o:","opcoes":["Autor","Réu","Juiz","Perito"],"explicacao":"Art. 373, I, do CPC."},{"id":1498,"materia":"pciv","nivel":1,"enunciado":"Em regra, quem deve provar o fato que impede, modifica ou extingue o direito do autor é o:","opcoes":["Réu","Autor","Juiz","Escrivão"],"explicacao":"Art. 373, II, do CPC."},{"id":1499,"materia":"pciv","nivel":1,"enunciado":"Depois da contestação, o autor pode desistir da ação sem o consentimento do réu?","opcoes":["Não","Sim, a qualquer tempo","Sim, se pagar custas","Sim, se o juiz quiser"],"explicacao":"Art. 485, § 4º, do CPC."},{"id":1500,"materia":"pciv","nivel":1,"enunciado":"A parte sem recursos para pagar as custas do processo tem direito à:","opcoes":["Gratuidade da justiça","Isenção de toda dívida","Escolha do juiz","Dispensa de advogado"],"explicacao":"Art. 98 do CPC."},{"id":1501,"materia":"pciv","nivel":1,"enunciado":"A audiência de instrução e julgamento serve principalmente para:","opcoes":["Colher as provas orais","Citar o réu do processo","Distribuir a ação","Calcular as custas"],"explicacao":"Ouvem-se partes, testemunhas e peritos."},{"id":1502,"materia":"pciv","nivel":1,"enunciado":"Quem nomeia o perito no processo civil?","opcoes":["O juiz","As partes","O escrivão","O tribunal"],"explicacao":"Art. 465 do CPC. As partes podem indicar assistentes técnicos."},{"id":1503,"materia":"pciv","nivel":1,"enunciado":"Pelo CPC, tem capacidade para estar em juízo:","opcoes":["Quem está no exercício de seus direitos","Apenas quem tem curso superior completo","Apenas as pessoas jurídicas registradas","Apenas os maiores de 21 anos de idade"],"explicacao":"Art. 70 do CPC."},{"id":1504,"materia":"pciv","nivel":1,"enunciado":"Os embargos de declaração servem para:","opcoes":["Esclarecer obscuridade, omissão ou contradição","Rediscutir todas as provas já produzidas no processo","Substituir a apelação em qualquer caso","Pedir a citação de outro réu esquecido"],"explicacao":"Art. 1.022 do CPC. Também corrigem erro material."},{"id":1505,"materia":"pciv","nivel":1,"enunciado":"Pelo princípio da inércia, o juiz:","opcoes":["Só age se for provocado","Inicia as ações de ofício","Escolhe as partes do processo","Dispensa o pedido do autor"],"explicacao":"Art. 2º do CPC."},{"id":1506,"materia":"pciv","nivel":1,"enunciado":"O Juizado Especial Cível estadual julga causas de até:","opcoes":["40 salários mínimos","60 salários mínimos","20 salários mínimos","100 salários mínimos"],"explicacao":"Art. 3º da Lei 9.099/1995. Os juizados federais vão até 60."},{"id":1507,"materia":"trib","nivel":1,"enunciado":"Quem cobra o tributo, como credor da obrigação, é o:","opcoes":["Sujeito ativo","Sujeito passivo","Contribuinte","Responsável"],"explicacao":"Art. 119 do CTN. É o ente com competência para exigir o tributo."},{"id":1508,"materia":"trib","nivel":1,"enunciado":"O ITCMD incide sobre:","opcoes":["Herança e doações","Venda de imóveis","Renda das pessoas","Propriedade de veículos"],"explicacao":"Imposto sobre transmissão causa mortis e doação."},{"id":1509,"materia":"trib","nivel":1,"enunciado":"O ITBI, cobrado na compra e venda de imóveis, é de competência:","opcoes":["Dos municípios","Dos estados","Da União","Dos cartórios"],"explicacao":"Art. 156, II, da Constituição."},{"id":1510,"materia":"trib","nivel":1,"enunciado":"O ITCMD é de competência:","opcoes":["Dos estados","Dos municípios","Da União","Dos cartórios"],"explicacao":"Art. 155, I, da Constituição."},{"id":1511,"materia":"trib","nivel":1,"enunciado":"O IPI é de competência:","opcoes":["Da União","Dos estados","Dos municípios","Dos estados e do DF"],"explicacao":"Art. 153, IV, da Constituição."},{"id":1512,"materia":"trib","nivel":1,"enunciado":"O imposto é um tributo:","opcoes":["Não vinculado a atuação estatal","Vinculado a serviço público","Vinculado a obra pública","Pago só por empresas"],"explicacao":"Art. 16 do CTN."},{"id":1513,"materia":"trib","nivel":1,"enunciado":"A taxa é um tributo:","opcoes":["Vinculado a uma atuação estatal","Não vinculado a nenhuma atividade","Cobrado só sobre a renda","Pago só por empresas"],"explicacao":"Decorre do poder de polícia ou de serviço público."},{"id":1514,"materia":"trib","nivel":1,"enunciado":"Os templos de qualquer culto têm imunidade de:","opcoes":["Impostos","Todos os tributos","Taxas","Contribuições"],"explicacao":"Art. 150, VI, “b”, da Constituição."},{"id":1515,"materia":"trib","nivel":1,"enunciado":"Partidos políticos, sindicatos de trabalhadores e entidades de educação sem fins lucrativos são imunes a:","opcoes":["Impostos sobre patrimônio, renda e serviços","Todas as taxas e contribuições sociais","Multas de trânsito e infrações em geral","Qualquer tipo de cobrança feita pelo Estado"],"explicacao":"Art. 150, VI, “c”, atendidos os requisitos da lei."},{"id":1516,"materia":"trib","nivel":1,"enunciado":"A obrigação tributária principal tem por objeto:","opcoes":["O pagamento de tributo ou penalidade","Apenas emitir notas fiscais de venda","Apenas manter os livros contábeis","Apenas prestar declarações ao fisco"],"explicacao":"Art. 113, § 1º, do CTN."},{"id":1517,"materia":"trib","nivel":1,"enunciado":"A obrigação tributária acessória envolve deveres como:","opcoes":["Emitir nota fiscal e declarar","Pagar o imposto devido no mês","Pagar a multa por atraso no tributo","Pagar os juros de mora acumulados"],"explicacao":"Art. 113, § 2º, do CTN."},{"id":1518,"materia":"trib","nivel":1,"enunciado":"O descumprimento de obrigação acessória:","opcoes":["Gera multa, que vira obrigação principal","Não gera nenhuma consequência jurídica","Extingue o crédito tributário existente","Gera a prisão imediata do contribuinte"],"explicacao":"Art. 113, § 3º, do CTN."},{"id":1519,"materia":"trib","nivel":1,"enunciado":"O contribuinte é o sujeito passivo que:","opcoes":["Tem relação direta com o fato gerador","Paga só por determinação da lei","Fiscaliza o pagamento do tributo","Julga os recursos tributários"],"explicacao":"Art. 121, parágrafo único, I, do CTN."},{"id":1520,"materia":"trib","nivel":1,"enunciado":"O responsável tributário é quem:","opcoes":["Paga por força de lei, sem ser contribuinte","Pratica pessoal e diretamente o fato gerador","Fiscaliza a arrecadação do tributo devido","Cria o tributo por meio de lei aprovada"],"explicacao":"Art. 121, parágrafo único, II, do CTN."},{"id":1521,"materia":"trib","nivel":1,"enunciado":"O lançamento de ofício é feito:","opcoes":["Pela autoridade, sem participação do contribuinte","Pelo contribuinte, que calcula e paga sozinho","Pelo juiz, em processo de execução","Pelo banco, no momento do pagamento"],"explicacao":"Art. 149 do CTN."},{"id":1522,"materia":"trib","nivel":1,"enunciado":"O IPTU é exemplo típico de lançamento:","opcoes":["De ofício","Por homologação","Por declaração","Por arbitragem"],"explicacao":"A prefeitura calcula e envia o carnê."},{"id":1523,"materia":"trib","nivel":1,"enunciado":"No lançamento por homologação, quem apura e paga antes do exame do fisco é:","opcoes":["O contribuinte","O fisco estadual","O juiz da execução","O banco arrecadador"],"explicacao":"Art. 150 do CTN. Depois, o fisco homologa ou cobra a diferença."},{"id":1524,"materia":"trib","nivel":1,"enunciado":"O IOF é de competência:","opcoes":["Da União","Dos estados","Dos municípios","Do Banco Central"],"explicacao":"Art. 153, V, da Constituição."},{"id":1525,"materia":"afo","nivel":1,"enunciado":"A LDO compreende, entre outros pontos:","opcoes":["As metas e prioridades da administração","A lista de todos os servidores públicos","As sentenças judiciais do ano","O valor de cada imposto"],"explicacao":"Art. 165, § 2º, da Constituição."},{"id":1526,"materia":"afo","nivel":1,"enunciado":"A LOA compreende o orçamento fiscal, o da seguridade social e o:","opcoes":["De investimento das estatais","Dos partidos políticos registrados","Das empresas privadas concessionárias","Dos sindicatos de servidores"],"explicacao":"Art. 165, § 5º, da Constituição."},{"id":1527,"materia":"afo","nivel":1,"enunciado":"Pelo princípio da anualidade, o orçamento:","opcoes":["Vale para um exercício financeiro","Vale por quatro anos seguidos","Vale enquanto durar o mandato","Não tem prazo definido"],"explicacao":"O exercício financeiro coincide com o ano civil."},{"id":1528,"materia":"afo","nivel":1,"enunciado":"O princípio da publicidade orçamentária exige:","opcoes":["A divulgação oficial do orçamento","O sigilo total das contas públicas","A aprovação prévia do Judiciário","A consulta aos bancos credores"],"explicacao":"Permite o controle pela sociedade."},{"id":1529,"materia":"afo","nivel":1,"enunciado":"Pelo princípio da unidade, deve existir:","opcoes":["Um único orçamento para cada ente","Um orçamento para cada ministério","Um orçamento por semestre","Vários orçamentos paralelos"],"explicacao":"Art. 2º da Lei 4.320/1964."},{"id":1530,"materia":"afo","nivel":1,"enunciado":"O pagamento de juros da dívida pública é despesa:","opcoes":["Corrente","De capital","De investimento","Extraorçamentária"],"explicacao":"Juros e encargos são despesas correntes; a amortização da dívida é de capital."},{"id":1531,"materia":"afo","nivel":1,"enunciado":"A construção de uma escola é despesa:","opcoes":["De capital","Corrente","De custeio","De pessoal"],"explicacao":"É um investimento."},{"id":1532,"materia":"afo","nivel":1,"enunciado":"A compra de material de consumo, como papel e tinta, é despesa:","opcoes":["Corrente","De capital","De investimento","De inversão financeira"],"explicacao":"É despesa de custeio."},{"id":1533,"materia":"afo","nivel":1,"enunciado":"A venda de um imóvel público gera receita:","opcoes":["De capital","Corrente","Tributária","Patrimonial"],"explicacao":"É alienação de bens."},{"id":1534,"materia":"afo","nivel":1,"enunciado":"Os impostos e taxas arrecadados são receita:","opcoes":["Corrente tributária","De capital","De operação de crédito","Extraorçamentária"],"explicacao":"Lei 4.320/1964, art. 11."},{"id":1535,"materia":"afo","nivel":1,"enunciado":"A dotação orçamentária é:","opcoes":["O valor autorizado na LOA para uma despesa","O dinheiro que sobrou no caixa no fim do ano","A dívida total acumulada pelo ente público","O total de impostos arrecadados no mês"],"explicacao":"É o limite que pode ser gasto naquela despesa."},{"id":1536,"materia":"afo","nivel":1,"enunciado":"Quem aprova a lei orçamentária é o:","opcoes":["Poder Legislativo","Poder Judiciário","Tribunal de Contas","Ministério Público"],"explicacao":"Na União, o Congresso Nacional."},{"id":1537,"materia":"afo","nivel":1,"enunciado":"Os créditos adicionais são:","opcoes":["Autorizações de despesa não prevista ou insuficiente","Receitas extras arrecadadas no fim do ano","Empréstimos feitos a servidores","Multas aplicadas pelo Tribunal de Contas"],"explicacao":"Art. 40 da Lei 4.320/1964."},{"id":1538,"materia":"afo","nivel":1,"enunciado":"Na LRF, a sigla RCL significa:","opcoes":["Receita corrente líquida","Reserva de caixa legal","Restos de crédito liquidado","Receita de capital lançada"],"explicacao":"É a base de cálculo dos limites da LRF."},{"id":1539,"materia":"afo","nivel":1,"enunciado":"A LRF busca principalmente:","opcoes":["Responsabilidade e equilíbrio na gestão fiscal","Aumentar a arrecadação de qualquer forma","Eliminar o controle das contas públicas","Permitir déficits sem nenhum limite"],"explicacao":"Art. 1º da LC 101/2000."},{"id":1540,"materia":"afo","nivel":1,"enunciado":"No orçamento, o Tribunal de Contas atua no:","opcoes":["Controle externo, auxiliando o Legislativo","Controle interno de cada órgão público","Julgamento dos crimes contra as finanças","Envio do projeto da LOA ao Congresso"],"explicacao":"Art. 71 da Constituição."},{"id":1541,"materia":"afo","nivel":1,"enunciado":"Pela LRF, os relatórios fiscais devem ser divulgados:","opcoes":["Também em meios eletrônicos de acesso público","Apenas em papel, na sede do próprio órgão","Somente quando houver pedido judicial","Só ao fim do mandato do governante"],"explicacao":"Art. 48 da LRF, sobre transparência."},{"id":1542,"materia":"afo","nivel":1,"enunciado":"Despesa empenhada e liquidada, mas não paga até 31/12, é inscrita em restos a pagar:","opcoes":["Processados","Não processados","Cancelados","Extraorçamentários"],"explicacao":"Os não processados são os empenhados e ainda não liquidados."},{"id":1543,"materia":"gest","nivel":1,"enunciado":"A visão de uma organização é:","opcoes":["Onde ela quer chegar no futuro","A sua razão de existir hoje","A lista de valores da equipe","O resultado financeiro do ano"],"explicacao":"A razão de existir é a missão."},{"id":1544,"materia":"gest","nivel":1,"enunciado":"Os valores organizacionais são:","opcoes":["Princípios que guiam o comportamento","Metas financeiras do próximo semestre","A estrutura de cargos e salários","O orçamento anual aprovado"],"explicacao":"Ex.: ética, transparência, respeito."},{"id":1545,"materia":"gest","nivel":1,"enunciado":"Efetividade é:","opcoes":["O impacto real gerado na sociedade","Usar bem os recursos disponíveis","Cumprir as metas internas","Gastar menos que o previsto"],"explicacao":"Eficiência é usar bem os recursos; eficácia, atingir objetivos."},{"id":1546,"materia":"gest","nivel":1,"enunciado":"O planejamento tático é feito no nível:","opcoes":["Intermediário","Institucional","Operacional","Técnico"],"explicacao":"Desdobra o estratégico para áreas e departamentos."},{"id":1547,"materia":"gest","nivel":1,"enunciado":"O planejamento operacional é de:","opcoes":["Curto prazo, para tarefas","Longo prazo, para a organização","Médio prazo, para áreas","Prazo indefinido"],"explicacao":"Detalha a execução do dia a dia."},{"id":1548,"materia":"gest","nivel":1,"enunciado":"A estrutura com hierarquia rígida, em que cada um tem um só chefe, é a:","opcoes":["Linear","Matricial","Em rede","Por projetos"],"explicacao":"Baseia-se na unidade de comando."},{"id":1549,"materia":"gest","nivel":1,"enunciado":"O organograma representa:","opcoes":["A estrutura formal da organização","A sequência das etapas de um processo","O orçamento aprovado para o ano","As metas individuais da equipe"],"explicacao":"Mostra órgãos e relações de hierarquia."},{"id":1550,"materia":"gest","nivel":1,"enunciado":"O fluxograma representa:","opcoes":["A sequência de um processo","A estrutura de cargos e chefias","O balanço patrimonial do ano","A missão e a visão da empresa"],"explicacao":"Mostra as etapas e decisões de um processo."},{"id":1551,"materia":"gest","nivel":1,"enunciado":"Na análise SWOT, as fraquezas são fatores:","opcoes":["Internos","Externos","Financeiros","Ambientais"],"explicacao":"Forças e fraquezas estão dentro da organização."},{"id":1552,"materia":"gest","nivel":1,"enunciado":"Uma meta SMART é específica, mensurável, atingível, relevante e:","opcoes":["Com prazo definido","Sem prazo definido","Secreta","Opcional"],"explicacao":"O T vem de time-bound."},{"id":1553,"materia":"gest","nivel":1,"enunciado":"O ciclo PDCA começa pela etapa de:","opcoes":["Planejar","Executar","Verificar","Agir"],"explicacao":"Plan, Do, Check, Act."},{"id":1554,"materia":"gest","nivel":1,"enunciado":"A motivação extrínseca vem de:","opcoes":["Recompensas externas, como salário","Satisfação com a própria tarefa","Interesse pessoal pelo assunto","Prazer em aprender"],"explicacao":"A intrínseca vem do próprio trabalho."},{"id":1555,"materia":"gest","nivel":1,"enunciado":"A comunicação formal é a que segue:","opcoes":["Os canais oficiais da organização","Conversas de corredor entre colegas","Boatos que circulam entre a equipe","Redes sociais pessoais dos chefes"],"explicacao":"A informal circula fora dos canais oficiais."},{"id":1556,"materia":"gest","nivel":1,"enunciado":"A rede informal de comunicação nas organizações é chamada de:","opcoes":["Rádio-peão","Organograma","Cadeia de comando","Fluxograma"],"explicacao":"Também conhecida como grapevine."},{"id":1557,"materia":"gest","nivel":1,"enunciado":"O controle preventivo ocorre:","opcoes":["Antes da execução da atividade","Depois que a atividade termina","Só durante auditorias externas","Só no fechamento do exercício"],"explicacao":"O concomitante ocorre durante; o posterior, depois."},{"id":1558,"materia":"gest","nivel":1,"enunciado":"Pelo princípio da unidade de comando, cada subordinado:","opcoes":["Deve ter um único chefe","Pode ter vários chefes","Escolhe o próprio chefe","Não precisa de chefe"],"explicacao":"Princípio de Fayol."},{"id":1559,"materia":"gest","nivel":1,"enunciado":"A amplitude de controle é:","opcoes":["O número de subordinados de um chefe","O tempo máximo de uma reunião","O tamanho do orçamento do setor","A duração prevista de um projeto"],"explicacao":"Quanto maior, mais achatada a estrutura."},{"id":1560,"materia":"gest","nivel":1,"enunciado":"A gestão por resultados dá foco a:","opcoes":["Metas e indicadores de desempenho","Regras e procedimentos rígidos","Apenas a hierarquia formal","Apenas o tempo de serviço"],"explicacao":"Característica do modelo gerencial."},{"id":1561,"materia":"arq","nivel":1,"enunciado":"Gravações de áudio de reuniões são documentos de gênero:","opcoes":["Sonoro","Textual","Iconográfico","Cartográfico"],"explicacao":"Registram a informação por meio de sons."},{"id":1562,"materia":"arq","nivel":1,"enunciado":"Filmes e vídeos são documentos de gênero:","opcoes":["Filmográfico","Sonoro","Textual","Cartográfico"],"explicacao":"Registram imagens em movimento."},{"id":1563,"materia":"arq","nivel":1,"enunciado":"O documento produzido originalmente em meio digital é chamado de:","opcoes":["Nato-digital","Digitalizado","Microfilmado","Iconográfico"],"explicacao":"O digitalizado é a versão digital de um original em papel."},{"id":1564,"materia":"arq","nivel":1,"enunciado":"Digitalizar um documento em papel gera:","opcoes":["Uma representação digital do original","Um novo documento original e autônomo","A eliminação automática do papel","Um documento sigiloso por natureza"],"explicacao":"O original em papel continua sujeito às regras de guarda."},{"id":1565,"materia":"arq","nivel":1,"enunciado":"O arquivo central é aquele que:","opcoes":["Reúne documentos de vários setores","Fica junto ao setor que produz","Guarda só documentos digitais","Guarda só documentos históricos"],"explicacao":"O que fica junto ao setor é o arquivo setorial."},{"id":1566,"materia":"arq","nivel":1,"enunciado":"A gestão de documentos abrange produção, tramitação, uso, avaliação e:","opcoes":["Arquivamento nas fases corrente e intermediária","Venda dos documentos antigos a colecionadores","Publicação de todos os documentos na internet","Restauração de obras de arte do acervo"],"explicacao":"Art. 3º da Lei 8.159/1991."},{"id":1567,"materia":"arq","nivel":1,"enunciado":"O documento ostensivo é aquele:","opcoes":["Sem restrição de acesso","Com acesso restrito por lei","Que já foi eliminado","Que só existe em papel"],"explicacao":"Opõe-se ao documento sigiloso."},{"id":1568,"materia":"arq","nivel":1,"enunciado":"O documento sigiloso é aquele:","opcoes":["Com acesso restrito por lei","Disponível a qualquer pessoa","Que já foi eliminado","Que só existe em meio digital"],"explicacao":"A Lei de Acesso à Informação define os graus de sigilo."},{"id":1569,"materia":"arq","nivel":1,"enunciado":"O método alfabético é considerado um método:","opcoes":["Direto","Indireto","Semi-indireto","Ideográfico"],"explicacao":"A busca é feita direto na pasta, sem índice."},{"id":1570,"materia":"arq","nivel":1,"enunciado":"O método numérico é considerado um método:","opcoes":["Indireto","Direto","Geográfico","Cronológico"],"explicacao":"Precisa de um índice para localizar o documento."},{"id":1571,"materia":"arq","nivel":1,"enunciado":"Organizar documentos por assunto corresponde ao método:","opcoes":["Ideográfico","Geográfico","Cronológico","Onomástico"],"explicacao":"Pode ser alfabético ou numérico por assunto."},{"id":1572,"materia":"arq","nivel":1,"enunciado":"Qual destas é uma atividade do protocolo?","opcoes":["Registrar a entrada de documentos","Definir o valor histórico do acervo","Restaurar documentos danificados","Elaborar o guia do arquivo"],"explicacao":"Também classifica, distribui, controla e expede."},{"id":1573,"materia":"arq","nivel":1,"enunciado":"A unidade que reúne documentos sobre um mesmo assunto ou caso é o:","opcoes":["Dossiê","Fundo","Catálogo","Guia"],"explicacao":"O fundo reúne documentos de uma mesma proveniência."},{"id":1574,"materia":"arq","nivel":1,"enunciado":"A higienização de documentos serve para:","opcoes":["Remover sujeira e agentes de deterioração","Apagar informações sigilosas do documento","Eliminar os documentos sem valor histórico","Digitalizar o acervo inteiro de uma vez"],"explicacao":"É uma ação de conservação preventiva."},{"id":1575,"materia":"arq","nivel":1,"enunciado":"Qual destes é um fator de deterioração do papel?","opcoes":["Umidade excessiva","Ambiente climatizado","Caixas de material neutro","Luz controlada"],"explicacao":"Favorece fungos e insetos."},{"id":1576,"materia":"arq","nivel":1,"enunciado":"Para conservar documentos, a temperatura e a umidade devem ser:","opcoes":["Estáveis e controladas","Altas e variáveis","Baixas e variáveis","Iguais às do ambiente externo"],"explicacao":"Variações bruscas danificam o papel."},{"id":1577,"materia":"arq","nivel":1,"enunciado":"Arquivos públicos são documentos produzidos e recebidos por:","opcoes":["Órgãos públicos em suas atividades","Pessoas físicas em suas casas","Empresas privadas em geral","Associações de bairro"],"explicacao":"Art. 7º da Lei 8.159/1991."},{"id":1578,"materia":"arq","nivel":1,"enunciado":"Arquivos privados são documentos produzidos por:","opcoes":["Pessoas físicas ou jurídicas privadas","Apenas órgãos do governo federal","Apenas tribunais e juízes estaduais","Apenas cartórios de registro civil"],"explicacao":"Art. 11 da Lei 8.159/1991."},{"id":1579,"materia":"port","nivel":4,"enunciado":"Em “Não fosse a chuva, teríamos saído”, a oração “Não fosse a chuva” tem valor:","opcoes":["Condicional","Causal","Concessivo","Temporal"],"explicacao":"Equivale a “Se não fosse a chuva”."},{"id":1580,"materia":"port","nivel":4,"enunciado":"Em “Quem tudo quer tudo perde”, a oração “Quem tudo quer” é subordinada substantiva:","opcoes":["Subjetiva","Objetiva direta","Predicativa","Apositiva"],"explicacao":"Funciona como sujeito de “perde”."},{"id":1581,"materia":"port","nivel":4,"enunciado":"Em “Meu desejo é que você passe”, a oração “que você passe” é substantiva:","opcoes":["Predicativa","Subjetiva","Objetiva direta","Completiva nominal"],"explicacao":"Vem depois do verbo de ligação e caracteriza o sujeito “meu desejo”."},{"id":1582,"materia":"port","nivel":4,"enunciado":"Em “Só quero uma coisa: que você passe”, a oração “que você passe” é substantiva:","opcoes":["Apositiva","Predicativa","Subjetiva","Objetiva indireta"],"explicacao":"Explica o termo “uma coisa”, depois dos dois-pontos."},{"id":1583,"materia":"port","nivel":4,"enunciado":"Em “Tenho certeza de que passarei”, a oração “de que passarei” é substantiva:","opcoes":["Completiva nominal","Objetiva indireta","Objetiva direta","Apositiva"],"explicacao":"Completa o substantivo “certeza”."},{"id":1584,"materia":"port","nivel":4,"enunciado":"Em “Lembro-me de que ele veio”, a oração “de que ele veio” é substantiva:","opcoes":["Objetiva indireta","Completiva nominal","Subjetiva","Predicativa"],"explicacao":"Completa o verbo pronominal “lembrar-se”, que pede “de”."},{"id":1585,"materia":"port","nivel":4,"enunciado":"Em “Que lindo dia!”, a palavra “que” é:","opcoes":["Advérbio de intensidade","Pronome relativo","Conjunção integrante","Preposição acidental"],"explicacao":"Intensifica o adjetivo “lindo”."},{"id":1586,"materia":"port","nivel":4,"enunciado":"Em “Ele é tal qual o pai”, a expressão “tal qual” é conjunção:","opcoes":["Comparativa","Conformativa","Consecutiva","Concessiva"],"explicacao":"Estabelece uma comparação entre ele e o pai."},{"id":1587,"materia":"port","nivel":4,"enunciado":"Qual palavra segue o Acordo Ortográfico quanto ao hífen?","opcoes":["Anti-inflamatório","Antiinflamatório","Auto-escola","Micro-empresa"],"explicacao":"Prefixo terminado na mesma vogal que inicia a palavra seguinte pede hífen. Autoescola e microempresa são juntas."},{"id":1588,"materia":"port","nivel":4,"enunciado":"Qual frase respeita a colocação pronominal da norma-padrão?","opcoes":["Tudo se resolveu a tempo.","Tudo resolveu-se a tempo.","Me disseram a verdade cedo.","Ninguém contou-me o fato."],"explicacao":"Pronomes indefinidos como “tudo” e “ninguém” atraem o pronome para antes do verbo."},{"id":1589,"materia":"const","nivel":4,"enunciado":"Qual destes legitimados precisa demonstrar pertinência temática para propor ADI?","opcoes":["Governador e Mesa de Assembleia","Presidente da República e PGR","Conselho Federal da OAB","Partido com representação no Congresso"],"explicacao":"Também as confederações sindicais e entidades de classe de âmbito nacional."},{"id":1590,"materia":"const","nivel":4,"enunciado":"Para propor ADC, é preciso demonstrar:","opcoes":["Controvérsia judicial relevante sobre a norma","Prejuízo financeiro direto e comprovado do autor","Aprovação prévia da ação pelo Senado Federal","Que a lei tenha sido aprovada há mais de 5 anos"],"explicacao":"Art. 14, III, da Lei 9.868/1999."},{"id":1591,"materia":"const","nivel":4,"enunciado":"Pode ser objeto de ação declaratória de constitucionalidade:","opcoes":["Lei ou ato normativo federal","Lei estadual ou distrital","Lei municipal","Qualquer ato de qualquer ente"],"explicacao":"Art. 102, I, “a”, da Constituição. A ADI alcança também normas estaduais."},{"id":1592,"materia":"const","nivel":4,"enunciado":"Pela Lei 11.417/2006, podem propor a edição de súmula vinculante, entre outros:","opcoes":["Os legitimados para propor ADI","Qualquer cidadão eleitor em dia","Apenas o Presidente do STF, sozinho","Apenas os juízes de 1º grau do país"],"explicacao":"Também o Defensor Público-Geral da União e os tribunais, entre outros."},{"id":1593,"materia":"const","nivel":4,"enunciado":"Contra decisão judicial que contraria súmula vinculante, cabe:","opcoes":["Reclamação ao STF","Mandado de injunção","Ação popular","Habeas data"],"explicacao":"Art. 103-A, § 3º, da Constituição."},{"id":1594,"materia":"const","nivel":4,"enunciado":"O poder constituinte derivado decorrente é o que permite:","opcoes":["Aos estados elaborar suas constituições","Ao Congresso aprovar emendas à Constituição","Ao povo criar uma nova Constituição Federal","Ao STF editar súmulas com efeito vinculante"],"explicacao":"Art. 25 da Constituição e art. 11 do ADCT."},{"id":1595,"materia":"const","nivel":4,"enunciado":"As normas constitucionais de eficácia contida:","opcoes":["Têm aplicação imediata, mas a lei pode restringi-las","Só produzem efeitos depois de regulamentadas por lei","Nunca podem ser restringidas por lei ou decreto","Valem apenas para os estados e o Distrito Federal"],"explicacao":"Ex.: liberdade profissional (art. 5º, XIII)."},{"id":1596,"materia":"const","nivel":4,"enunciado":"As normas constitucionais de eficácia limitada:","opcoes":["Dependem de lei para produzir todos os efeitos","Têm aplicação imediata, integral e definitiva","Podem ser restringidas por qualquer lei ordinária","Revogam todas as leis anteriores contrárias"],"explicacao":"Ex.: direito de greve do servidor (art. 37, VII)."},{"id":1597,"materia":"const","nivel":4,"enunciado":"A competência do Senado para suspender a execução de lei declarada inconstitucional pelo STF está no art.:","opcoes":["52, X","102, I","97","60, § 4º"],"explicacao":"É um mecanismo ligado ao controle difuso de constitucionalidade."},{"id":1598,"materia":"adm","nivel":4,"enunciado":"Pelo STF (Tema 940), a vítima de dano causado por agente público deve processar:","opcoes":["O Estado, e não o agente diretamente","Apenas o agente, pessoalmente","O agente e o Estado, obrigatoriamente juntos","O Tribunal de Contas responsável"],"explicacao":"É a teoria da dupla garantia. O Estado depois cobra o agente em regresso."},{"id":1599,"materia":"adm","nivel":4,"enunciado":"Pela Lei 9.784/1999, os atos com defeitos sanáveis, sem lesão ao interesse público nem prejuízo a terceiros, podem ser:","opcoes":["Convalidados","Apenas anulados","Apenas revogados","Ignorados"],"explicacao":"Art. 55 da Lei 9.784/1999."},{"id":1600,"materia":"adm","nivel":4,"enunciado":"Pela Lei 9.784/1999, o processo administrativo pode ser iniciado:","opcoes":["De ofício ou a pedido do interessado","Somente a pedido do interessado","Somente por ordem judicial","Somente pelo Tribunal de Contas"],"explicacao":"Art. 5º da Lei 9.784/1999."},{"id":1601,"materia":"adm","nivel":4,"enunciado":"Na Lei 14.133/2021, a fase preparatória da licitação é marcada pelo:","opcoes":["Planejamento e estudo técnico preliminar","Julgamento das propostas já recebidas","Recurso contra o resultado final da disputa","Pagamento do contrato depois de assinado"],"explicacao":"Art. 18 da Lei 14.133/2021."},{"id":1602,"materia":"adm","nivel":4,"enunciado":"Na Lei 14.133/2021, o Portal Nacional de Contratações Públicas (PNCP) serve para:","opcoes":["Divulgar atos de licitações e contratos","Julgar os recursos contra licitações","Pagar os fornecedores da União","Punir empresas declaradas inidôneas"],"explicacao":"Art. 174 da Lei 14.133/2021."},{"id":1603,"materia":"adm","nivel":4,"enunciado":"A servidão administrativa é:","opcoes":["Direito real que onera imóvel para serviço público","Uso temporário de bem particular em perigo iminente","Transferência forçada da propriedade ao Estado","Proteção do patrimônio histórico e artístico"],"explicacao":"Ex.: passagem de linhas de transmissão de energia."},{"id":1604,"materia":"adm","nivel":4,"enunciado":"Pela Lei 8.987/1995, a retomada do serviço por interesse público, com lei autorizativa e indenização prévia, é a:","opcoes":["Encampação","Caducidade","Rescisão","Anulação"],"explicacao":"Art. 37 da Lei 8.987/1995."},{"id":1605,"materia":"adm","nivel":4,"enunciado":"Pela Lei 8.987/1995, a extinção da concessão por inadimplemento da concessionária é a:","opcoes":["Caducidade","Encampação","Reversão","Revogação"],"explicacao":"Art. 38 da Lei 8.987/1995."},{"id":1606,"materia":"adm","nivel":4,"enunciado":"Pela Lei 11.079/2004, o contrato de PPP não pode ter valor inferior a:","opcoes":["R$ 10 milhões","R$ 20 milhões","R$ 1 milhão","R$ 50 milhões"],"explicacao":"Art. 2º, § 4º, I, com redação da Lei 13.529/2017. O prazo vai de 5 a 35 anos."},{"id":1607,"materia":"pen","nivel":4,"enunciado":"Pela teoria finalista, adotada pelo Código Penal, o dolo e a culpa estão na:","opcoes":["Conduta, dentro do fato típico","Culpabilidade, como seus elementos","Ilicitude, como causas de exclusão","Punibilidade, como condições objetivas"],"explicacao":"Na teoria causalista, ficavam na culpabilidade."},{"id":1608,"materia":"pen","nivel":4,"enunciado":"Na teoria normativa pura, a culpabilidade reúne imputabilidade, potencial consciência da ilicitude e:","opcoes":["Exigibilidade de conduta diversa","Dolo e culpa","Nexo causal","Resultado naturalístico"],"explicacao":"Dolo e culpa ficam na conduta."},{"id":1609,"materia":"pen","nivel":4,"enunciado":"Qual destes é crime de mão própria, que só o próprio agente pode executar?","opcoes":["Falso testemunho","Peculato","Homicídio","Roubo"],"explicacao":"Admite participação, mas não coautoria nem autoria mediata, segundo a doutrina majoritária."},{"id":1610,"materia":"pen","nivel":4,"enunciado":"O crime próprio exige:","opcoes":["Qualidade especial do sujeito ativo","Resultado naturalístico separado da conduta","Violência ou grave ameaça contra a pessoa","Pluralidade de agentes agindo em conjunto"],"explicacao":"Ex.: peculato, que exige funcionário público."},{"id":1611,"materia":"pen","nivel":4,"enunciado":"No crime omissivo impróprio, o agente responde pelo resultado porque:","opcoes":["Tinha o dever jurídico de evitá-lo","Desejou diretamente aquele resultado","Usou meio cruel durante a execução","Agiu por motivo torpe ou fútil"],"explicacao":"Art. 13, § 2º, do Código Penal."},{"id":1612,"materia":"pen","nivel":4,"enunciado":"Pelo art. 13, § 2º, tem o dever de agir quem:","opcoes":["Criou o risco com conduta anterior","Apenas presenciou o fato","Ouviu falar do perigo","Passava pelo local por acaso"],"explicacao":"Também quem tem dever legal ou assumiu a responsabilidade de impedir o resultado."},{"id":1613,"materia":"pen","nivel":4,"enunciado":"A causa superveniente relativamente independente que, por si só, produz o resultado:","opcoes":["Exclui a imputação do resultado","Torna o crime mais grave","Não tem nenhum efeito","Transforma o crime em culposo"],"explicacao":"Art. 13, § 1º. O agente responde pelos fatos anteriores."},{"id":1614,"materia":"pen","nivel":4,"enunciado":"Pela Súmula 610 do STF, se a morte se consuma e a subtração fica tentada, há:","opcoes":["Latrocínio consumado","Latrocínio tentado","Homicídio e furto tentado","Roubo simples"],"explicacao":"O que importa para a consumação é a morte."},{"id":1615,"materia":"pen","nivel":4,"enunciado":"Pela Súmula 582 do STJ, o roubo se consuma com:","opcoes":["A inversão da posse, mesmo breve","A posse mansa e pacífica do bem","A venda do bem a terceiro","A saída do agente da cidade"],"explicacao":"Teoria da amotio ou apprehensio."},{"id":1616,"materia":"ppen","nivel":4,"enunciado":"Após o Pacote Anticrime, o CPP declara expressamente que o processo penal tem estrutura:","opcoes":["Acusatória","Inquisitiva","Mista","Inquisitorial reformada"],"explicacao":"Art. 3º-A do CPP."},{"id":1617,"materia":"ppen","nivel":4,"enunciado":"No tempo, a lei processual penal se aplica:","opcoes":["Desde logo, sem invalidar atos já feitos","Só aos crimes cometidos depois da vigência","Só se for mais benéfica ao réu no caso","Só depois de um ano da sua publicação"],"explicacao":"Art. 2º do CPP: tempus regit actum."},{"id":1618,"materia":"ppen","nivel":4,"enunciado":"Na conexão entre crime do júri e crime da jurisdição comum, prevalece a competência:","opcoes":["Do Tribunal do Júri","Do juiz singular","Do juizado especial","Do tribunal de justiça"],"explicacao":"Art. 78, I, do CPP."},{"id":1619,"materia":"ppen","nivel":4,"enunciado":"Pela Súmula 122 do STJ, havendo conexão entre crimes federal e estadual, a competência é:","opcoes":["Da Justiça Federal para ambos","Da Justiça Estadual para ambos","Separada, cada um na sua","Do STJ, originariamente"],"explicacao":"A Justiça Federal atrai o crime estadual conexo."},{"id":1620,"materia":"ppen","nivel":4,"enunciado":"Um roubo contra agência dos Correios, empresa pública federal, é julgado pela:","opcoes":["Justiça Federal","Justiça Estadual","Justiça Militar","Justiça Eleitoral"],"explicacao":"Art. 109, IV, da Constituição."},{"id":1621,"materia":"ppen","nivel":4,"enunciado":"Pode ser decretada prisão preventiva por crime culposo?","opcoes":["Não, o art. 313 exige crime doloso","Sim, sempre que houver risco","Sim, se a pena passar de 2 anos","Sim, se o réu for primário"],"explicacao":"Art. 313, I, do CPP."},{"id":1622,"materia":"ppen","nivel":4,"enunciado":"O habeas corpus contra ato de turma recursal de juizado especial criminal é julgado pelo:","opcoes":["Tribunal de Justiça","STF","STJ","Próprio juizado"],"explicacao":"Entendimento do STF, que superou a antiga Súmula 690."},{"id":1623,"materia":"ppen","nivel":4,"enunciado":"Pela Súmula 691 do STF, não cabe habeas corpus no STF contra:","opcoes":["Decisão de relator que nega liminar em HC no tribunal superior","Qualquer decisão do STJ em matéria penal, sem exceção","Sentença condenatória proferida por juiz de 1º grau","Acórdão de tribunal de justiça em recurso de apelação"],"explicacao":"O STF admite exceção em caso de flagrante ilegalidade."},{"id":1624,"materia":"ppen","nivel":4,"enunciado":"Na revisão criminal, o tribunal pode reconhecer ao réu o direito a:","opcoes":["Indenização pelos prejuízos sofridos","Promoção automática no serviço público","Isenção de todos os tributos por 10 anos","Escolha de outro juiz para novo processo"],"explicacao":"Art. 630 do CPP."},{"id":1625,"materia":"inf","nivel":4,"enunciado":"No modelo TCP/IP, o protocolo IP fica na camada de:","opcoes":["Internet","Aplicação","Transporte","Acesso à rede"],"explicacao":"Equivale à camada de rede do modelo OSI."},{"id":1626,"materia":"inf","nivel":4,"enunciado":"O protocolo ARP serve para:","opcoes":["Descobrir o endereço MAC a partir do IP","Traduzir nomes de domínio em IP","Distribuir endereços IP automaticamente","Enviar mensagens de erro na rede"],"explicacao":"DNS traduz nomes; DHCP distribui IPs; ICMP envia mensagens de erro."},{"id":1627,"materia":"inf","nivel":4,"enunciado":"Quantos bits tem um endereço MAC?","opcoes":["48","32","64","128"],"explicacao":"Costuma ser escrito em 6 pares hexadecimais."},{"id":1628,"materia":"inf","nivel":4,"enunciado":"O comando ping usa o protocolo:","opcoes":["ICMP","FTP","SMTP","SNMP"],"explicacao":"Envia mensagens de eco para testar a conectividade."},{"id":1629,"materia":"inf","nivel":4,"enunciado":"A porta 53 é usada pelo:","opcoes":["DNS","FTP","SSH","HTTP"],"explicacao":"FTP usa 20 e 21; SSH, 22; HTTP, 80."},{"id":1630,"materia":"inf","nivel":4,"enunciado":"O protocolo FTP usa as portas:","opcoes":["20 e 21","80 e 443","25 e 110","22 e 23"],"explicacao":"A 21 é de controle e a 20, de dados (modo ativo)."},{"id":1631,"materia":"inf","nivel":4,"enunciado":"A segurança do RSA se baseia na dificuldade de:","opcoes":["Fatorar números muito grandes","Somar números primos pequenos","Ordenar listas extensas","Comprimir arquivos grandes"],"explicacao":"É um algoritmo de criptografia assimétrica."},{"id":1632,"materia":"inf","nivel":4,"enunciado":"Um certificado digital da ICP-Brasil vincula uma chave pública a:","opcoes":["Uma pessoa ou entidade identificada","Um computador específico apenas","Uma senha de banco","Um endereço de IP fixo"],"explicacao":"Emitido por autoridade certificadora credenciada."},{"id":1633,"materia":"inf","nivel":4,"enunciado":"Qual o número mínimo de discos para montar um RAID 5?","opcoes":["3","2","4","5"],"explicacao":"Usa paridade distribuída e suporta a falha de um disco."},{"id":1634,"materia":"rl","nivel":4,"enunciado":"Quantas soluções inteiras não negativas tem a equação x + y + z = 5?","opcoes":["21","15","10","35"],"explicacao":"Combinação com repetição: C(7,2) = 21."},{"id":1635,"materia":"rl","nivel":4,"enunciado":"Um conjunto tem 6 elementos. Quantos subconjuntos de 3 elementos contêm um elemento específico?","opcoes":["10","20","15","6"],"explicacao":"Fixado o elemento, escolhem-se 2 dos 5 restantes: C(5,2) = 10."},{"id":1636,"materia":"rl","nivel":4,"enunciado":"Lançando um dado 3 vezes, qual a probabilidade de sair pelo menos um 6?","opcoes":["91/216","1/2","1/6","3/6"],"explicacao":"1 − (5/6)³ = 1 − 125/216 = 91/216."},{"id":1637,"materia":"rl","nivel":4,"enunciado":"A proposição (P → Q) ↔ (¬Q → ¬P) é:","opcoes":["Tautologia","Contradição","Contingência","Indeterminada"],"explicacao":"Uma condicional e sua contrapositiva são sempre equivalentes."},{"id":1638,"materia":"rl","nivel":4,"enunciado":"“Todo A é B” e “Algum C não é B”. Conclui-se que:","opcoes":["Algum C não é A","Todo C é A","Nenhum A é C","Algum A não é B"],"explicacao":"Os C que estão fora de B não podem estar em A, que está dentro de B."},{"id":1639,"materia":"rl","nivel":4,"enunciado":"Juros compostos de 1% ao mês equivalem a quanto ao bimestre?","opcoes":["2,01%","2%","1,01%","2,1%"],"explicacao":"1,01² = 1,0201."},{"id":1640,"materia":"rl","nivel":4,"enunciado":"R$ 1.000,00 a 10% ao ano, com capitalização semestral, rendem quanto em 1 ano?","opcoes":["R$ 102,50","R$ 100,00","R$ 105,00","R$ 110,00"],"explicacao":"Taxa de 5% ao semestre: 1.000 × 1,05² = 1.102,50."},{"id":1641,"materia":"rl","nivel":4,"enunciado":"60% gostam de A, 50% de B e 20% de nenhum. Quantos gostam de ambos?","opcoes":["30%","10%","20%","40%"],"explicacao":"80% gostam de pelo menos um: 60 + 50 − 80 = 30."},{"id":1642,"materia":"rl","nivel":4,"enunciado":"Com quantos zeros termina o número 25! (fatorial de 25)?","opcoes":["6","5","4","7"],"explicacao":"25 ÷ 5 = 5, e 25 ÷ 25 = 1. Total: 6 fatores 5."},{"id":1643,"materia":"dh","nivel":4,"enunciado":"Para a Corte Interamericana, leis de anistia que impedem investigar graves violações são:","opcoes":["Incompatíveis com a Convenção Americana","Válidas em qualquer caso e circunstância","Válidas, se aprovadas por plebiscito popular","Matéria exclusiva do direito interno do país"],"explicacao":"Casos Barrios Altos e Gomes Lund."},{"id":1644,"materia":"dh","nivel":4,"enunciado":"Na ADPF 153 (2010), o STF decidiu que a Lei de Anistia de 1979:","opcoes":["Foi recepcionada pela Constituição","É inconstitucional por inteiro","Foi revogada pela EC 45/2004","Vale apenas para militares"],"explicacao":"Decisão que contrasta com a sentença da Corte Interamericana no caso Gomes Lund."},{"id":1645,"materia":"dh","nivel":4,"enunciado":"A Revisão Periódica Universal do Conselho de Direitos Humanos da ONU avalia:","opcoes":["A situação de todos os Estados-membros","Apenas os países que estão em guerra","Apenas os países denunciados por ONGs","Apenas as empresas multinacionais"],"explicacao":"Todos os países são revisados periodicamente."},{"id":1646,"materia":"dh","nivel":4,"enunciado":"Os Princípios de Paris tratam das:","opcoes":["Instituições nacionais de direitos humanos","Regras de prisão de estrangeiros","Normas de extradição na Europa","Diretrizes para eleições livres"],"explicacao":"Exigem independência e mandato amplo dessas instituições."},{"id":1647,"materia":"dh","nivel":4,"enunciado":"Em que ano foi adotada a Convenção Interamericana para Prevenir e Punir a Tortura?","opcoes":["1985","1969","1994","1984"],"explicacao":"A convenção da ONU contra a tortura é de 1984."},{"id":1648,"materia":"dh","nivel":4,"enunciado":"As normas de jus cogens são:","opcoes":["Normas imperativas que não admitem derrogação","Recomendações internacionais sem força obrigatória","Leis internas aprovadas por cada país","Contratos firmados entre empresas estrangeiras"],"explicacao":"Art. 53 da Convenção de Viena sobre o Direito dos Tratados."},{"id":1649,"materia":"dh","nivel":4,"enunciado":"A proibição da tortura e da escravidão são exemplos de normas:","opcoes":["De jus cogens","Dispositivas","Programáticas","Consuetudinárias locais"],"explicacao":"Não podem ser afastadas nem por tratado."},{"id":1650,"materia":"dh","nivel":4,"enunciado":"Pelo art. 27 da Convenção de Viena sobre Tratados, um Estado não pode invocar seu direito interno para:","opcoes":["Justificar o descumprimento de um tratado","Aprovar uma nova Constituição nacional","Criar novos tribunais internos","Ratificar outros tratados internacionais"],"explicacao":"Vale também para os tratados de direitos humanos."},{"id":1651,"materia":"dh","nivel":4,"enunciado":"Qual decreto promulgou no Brasil a Convenção sobre os Direitos das Pessoas com Deficiência?","opcoes":["6.949/2009","678/1992","4.377/2002","99.710/1990"],"explicacao":"O 678 promulgou o Pacto de San José; o 4.377, a CEDAW; o 99.710, a Convenção sobre os Direitos da Criança."},{"id":1652,"materia":"leg","nivel":4,"enunciado":"O tráfico privilegiado (art. 33, § 4º, da Lei de Drogas) é crime hediondo?","opcoes":["Não, por decisão do STF e por lei","Sim, sempre","Só se houver arma","Só se for internacional"],"explicacao":"Art. 112, § 5º, da LEP, incluído pela Lei 13.964/2019."},{"id":1653,"materia":"leg","nivel":4,"enunciado":"Após o julgamento do STF de 2023, a competência do juiz das garantias vai até:","opcoes":["O oferecimento da denúncia","A sentença de 1º grau","O recebimento da apelação","O trânsito em julgado"],"explicacao":"ADIs 6.298 e outras. A lei previa até o recebimento da denúncia."},{"id":1654,"materia":"leg","nivel":4,"enunciado":"Na Lei 12.850/2013, a infiltração virtual de agentes pode durar:","opcoes":["6 meses, até 720 dias no total","30 dias, improrrogáveis","1 ano, sem renovação","90 dias, até 180 no total"],"explicacao":"Art. 10-A, § 4º."},{"id":1655,"materia":"leg","nivel":4,"enunciado":"As fases típicas da lavagem de dinheiro são colocação, ocultação e:","opcoes":["Integração","Apreensão","Restituição","Denúncia"],"explicacao":"Na integração, o dinheiro volta à economia com aparência lícita."},{"id":1656,"materia":"leg","nivel":4,"enunciado":"Segundo o STF e o STJ, o porte ilegal de arma é crime de perigo:","opcoes":["Abstrato","Concreto","De dano","Inexistente"],"explicacao":"Não exige prova de risco efetivo a alguém."},{"id":1657,"materia":"leg","nivel":4,"enunciado":"Pelo STJ, portar ilegalmente arma desmuniciada:","opcoes":["É crime, por ser de perigo abstrato","Não é crime, por falta de munição","É só infração administrativa","É crime apenas se houver vítima"],"explicacao":"A falta de munição não afasta o crime."},{"id":1658,"materia":"leg","nivel":4,"enunciado":"Pelo STJ, portar arma comprovadamente inapta para disparar:","opcoes":["Torna o fato atípico","É crime hediondo","É crime de perigo concreto","É sempre porte ilegal"],"explicacao":"Sem potencial lesivo atestado em perícia, não há crime."},{"id":1659,"materia":"leg","nivel":4,"enunciado":"Na lesão corporal leve, a representação do ofendido deve ser oferecida em:","opcoes":["6 meses, do conhecimento da autoria","30 dias, a contar da data do fato","1 ano, a contar da data do fato","2 anos, a contar da descoberta do crime"],"explicacao":"Art. 38 do CPP, aplicado aos crimes da Lei 9.099/1995."},{"id":1660,"materia":"leg","nivel":4,"enunciado":"Pelo CTB, a alteração da capacidade psicomotora (art. 306) pode ser provada por:","opcoes":["Bafômetro, exame, vídeo ou testemunha","Apenas exame de sangue em hospital","Apenas o teste do bafômetro na via","Apenas a confissão do próprio motorista"],"explicacao":"Art. 306, § 2º, do Código de Trânsito."},{"id":1661,"materia":"est","nivel":4,"enunciado":"X e Y são independentes, com Var(X) = 4 e Var(Y) = 9. Quanto vale Var(X − Y)?","opcoes":["13","5","−5","36"],"explicacao":"Para variáveis independentes, as variâncias se somam, mesmo na diferença."},{"id":1662,"materia":"est","nivel":4,"enunciado":"Uma covariância positiva entre X e Y indica que as variáveis:","opcoes":["Tendem a crescer juntas","Tendem a variar em sentidos opostos","São independentes","Têm a mesma média"],"explicacao":"Não indica a força da relação; para isso, usa-se a correlação."},{"id":1663,"materia":"est","nivel":4,"enunciado":"Qual a correlação entre X e Y = 2X + 3?","opcoes":["1","2","0","0,5"],"explicacao":"Relação linear perfeita e crescente."},{"id":1664,"materia":"est","nivel":4,"enunciado":"Qual a correlação entre X e Y = −X?","opcoes":["−1","1","0","−0,5"],"explicacao":"Relação linear perfeita e decrescente."},{"id":1665,"materia":"est","nivel":4,"enunciado":"No teste qui-quadrado de independência com tabela 3 × 4, quantos são os graus de liberdade?","opcoes":["6","12","7","5"],"explicacao":"(3 − 1) × (4 − 1) = 6."},{"id":1666,"materia":"est","nivel":4,"enunciado":"Uma exponencial tem média 5. Qual a sua variância?","opcoes":["25","5","10","√5"],"explicacao":"Na exponencial, a variância é o quadrado da média."},{"id":1667,"materia":"est","nivel":4,"enunciado":"Uma uniforme contínua no intervalo [0, 12] tem variância:","opcoes":["12","6","36","144"],"explicacao":"(b − a)² ÷ 12 = 144 ÷ 12 = 12."},{"id":1668,"materia":"est","nivel":4,"enunciado":"Qual o desvio médio absoluto de 2, 4 e 6?","opcoes":["4/3","2","4","0"],"explicacao":"Média 4. Desvios absolutos: 2, 0 e 2. Média: 4 ÷ 3."},{"id":1669,"materia":"est","nivel":4,"enunciado":"Numa amostra de 100 pessoas com proporção de 0,5, o erro padrão da proporção é:","opcoes":["0,05","0,5","0,025","0,0025"],"explicacao":"√(0,5 × 0,5 ÷ 100) = √0,0025 = 0,05."},{"id":1670,"materia":"cont","nivel":4,"enunciado":"Estoque inicial de 100 un. a R$ 10; compra de 100 un. a R$ 12; venda de 150 un. Pelo custo médio, o estoque final é de:","opcoes":["R$ 550","R$ 600","R$ 500","R$ 1.650"],"explicacao":"Custo médio de R$ 11; sobram 50 unidades × 11."},{"id":1671,"materia":"cont","nivel":4,"enunciado":"No mesmo caso (100 a R$ 10, 100 a R$ 12, venda de 150), pelo PEPS o estoque final é de:","opcoes":["R$ 600","R$ 550","R$ 500","R$ 1.700"],"explicacao":"Saem primeiro as 100 de R$ 10 e 50 de R$ 12. Sobram 50 a R$ 12."},{"id":1672,"materia":"cont","nivel":4,"enunciado":"Pelo CPC 27, a depreciação de um imobilizado começa quando:","opcoes":["O ativo está disponível para uso","O ativo é pago por completo","O exercício social se encerra","O ativo é vendido"],"explicacao":"Mesmo que ainda não esteja sendo usado."},{"id":1673,"materia":"cont","nivel":4,"enunciado":"Pelo CPC 01, há perda por impairment quando o valor contábil supera o:","opcoes":["Valor recuperável","Custo histórico","Valor residual","Preço de mercado do ano anterior"],"explicacao":"A diferença é reconhecida como perda no resultado."},{"id":1674,"materia":"cont","nivel":4,"enunciado":"O valor recuperável de um ativo é o maior entre:","opcoes":["Valor justo menos despesas de venda e valor em uso","Custo histórico de aquisição e valor residual estimado","Valor contábil líquido e depreciação acumulada","Preço de compra original e preço de venda atual"],"explicacao":"CPC 01."},{"id":1675,"materia":"cont","nivel":4,"enunciado":"Pelo CPC 06 (R2), o arrendatário reconhece, em regra:","opcoes":["Ativo de direito de uso e passivo de arrendamento","Apenas despesa de aluguel no resultado do mês","Apenas uma nota explicativa, sem lançamento","Receita de arrendamento no resultado do ano"],"explicacao":"Há exceções para contratos de curto prazo e de baixo valor."},{"id":1676,"materia":"cont","nivel":4,"enunciado":"Na DFC pelo método indireto, o aumento de clientes a receber é:","opcoes":["Subtraído do lucro líquido","Somado ao lucro líquido","Lançado em financiamento","Ignorado no cálculo do caixa"],"explicacao":"Parte das vendas não virou dinheiro."},{"id":1677,"materia":"cont","nivel":4,"enunciado":"Na DFC pelo método indireto, o aumento de fornecedores a pagar é:","opcoes":["Somado ao lucro líquido","Subtraído do lucro líquido","Lançado em investimento","Ignorado"],"explicacao":"Parte das compras ainda não saiu do caixa."},{"id":1678,"materia":"cont","nivel":4,"enunciado":"A reserva legal pode deixar de ser constituída quando, somada às reservas de capital, exceder:","opcoes":["30% do capital social","20% do capital social","50% do capital social","10% do capital social"],"explicacao":"Art. 193, § 1º, da Lei 6.404/1976."},{"id":1679,"materia":"civ","nivel":2,"enunciado":"Qual destes é relativamente incapaz, segundo o Código Civil?","opcoes":["O pródigo","O menor de 15 anos","O maior de 70 anos","O analfabeto"],"explicacao":"Art. 4º, IV. O menor de 16 é absolutamente incapaz."},{"id":1680,"materia":"civ","nivel":2,"enunciado":"Além da concessão dos pais, a emancipação também ocorre pelo:","opcoes":["Casamento","Alistamento eleitoral","Primeiro emprego informal","Ingresso no ensino médio"],"explicacao":"Art. 5º, parágrafo único, II."},{"id":1681,"materia":"civ","nivel":2,"enunciado":"A emancipação concedida pelos pais exige:","opcoes":["Instrumento público, sem homologação judicial","Sentença judicial, após ouvir o MP","Simples declaração verbal em cartório","Autorização do Conselho Tutelar"],"explicacao":"Art. 5º, parágrafo único, I."},{"id":1682,"materia":"civ","nivel":2,"enunciado":"A morte presumida pode ser declarada sem ausência quando:","opcoes":["For muito provável a morte de quem estava em perigo","A pessoa mudar de cidade sem avisar","A pessoa deixar de votar por 3 eleições","A família pedir, sem nenhuma prova do sumiço ou do perigo"],"explicacao":"Art. 7º, I, do Código Civil."},{"id":1683,"materia":"civ","nivel":2,"enunciado":"Uma fundação privada só pode ser criada para fins:","opcoes":["Não lucrativos, previstos no art. 62","Lucrativos de qualquer natureza","Exclusivamente políticos e eleitorais","Apenas comerciais e industriais"],"explicacao":"Art. 62, parágrafo único, do Código Civil."},{"id":1684,"materia":"civ","nivel":2,"enunciado":"Pelo Código Civil, o ato praticado em legítima defesa:","opcoes":["Não constitui ato ilícito","É sempre ato ilícito","Gera indenização em dobro","É nulo de pleno direito"],"explicacao":"Art. 188, I, do Código Civil."},{"id":1685,"materia":"civ","nivel":2,"enunciado":"Pelo art. 187, exercer um direito excedendo manifestamente seus limites é:","opcoes":["Ato ilícito (abuso de direito)","Ato lícito e protegido pela autonomia privada","Mero ato anulável","Fato jurídico natural"],"explicacao":"Os limites são o fim econômico ou social, a boa-fé e os bons costumes."},{"id":1686,"materia":"civ","nivel":2,"enunciado":"A cobrança de dívida líquida, constante de instrumento público ou particular, prescreve em:","opcoes":["5 anos","3 anos","10 anos","1 ano"],"explicacao":"Art. 206, § 5º, I, do Código Civil."},{"id":1687,"materia":"civ","nivel":2,"enunciado":"A prescrição pode ser alegada:","opcoes":["Em qualquer grau de jurisdição","Só na petição inicial","Só antes da citação do réu no processo","Só em recurso especial"],"explicacao":"Art. 193, pela parte a quem aproveita."},{"id":1688,"materia":"civ","nivel":2,"enunciado":"A renúncia à prescrição só é válida:","opcoes":["Depois de a prescrição se consumar","Antes de o prazo começar","No próprio contrato original","Por ordem judicial prévia"],"explicacao":"Art. 191 do Código Civil."},{"id":1689,"materia":"civ","nivel":2,"enunciado":"As partes podem alterar os prazos de prescrição por acordo?","opcoes":["Não","Sim, livremente","Sim, só para aumentar","Sim, só para reduzir"],"explicacao":"Art. 192 do Código Civil."},{"id":1690,"materia":"civ","nivel":2,"enunciado":"Na solidariedade passiva, o credor pode cobrar a dívida inteira de:","opcoes":["Qualquer um dos devedores","Apenas o devedor principal","Todos ao mesmo tempo, em partes","Apenas o último devedor"],"explicacao":"Art. 275 do Código Civil."},{"id":1691,"materia":"civ","nivel":2,"enunciado":"Pelo Código Civil, a solidariedade:","opcoes":["Não se presume; vem da lei ou da vontade","Presume-se em qualquer contrato com mais de um devedor","Só existe entre parentes","Só vale para dívidas trabalhistas"],"explicacao":"Art. 265 do Código Civil."},{"id":1692,"materia":"civ","nivel":2,"enunciado":"O pagamento feito de boa-fé a quem parecia ser o credor (credor putativo) é:","opcoes":["Válido, mesmo que se prove depois que não era credor","Nulo, devendo o devedor pagar de novo ao credor verdadeiro","Anulável a pedido do credor verdadeiro","Ineficaz até decisão judicial"],"explicacao":"Art. 309 do Código Civil."},{"id":1693,"materia":"civ","nivel":2,"enunciado":"A compensação extingue obrigações entre pessoas que são:","opcoes":["Credoras e devedoras uma da outra","Sócias da mesma empresa","Parentes até o terceiro grau, em linha reta ou colateral","Vizinhas de imóveis"],"explicacao":"Art. 368 do Código Civil."},{"id":1694,"materia":"civ","nivel":2,"enunciado":"Na novação:","opcoes":["Cria-se nova obrigação para extinguir a anterior","A dívida é perdoada sem nenhuma contrapartida","O credor transfere o crédito a outra pessoa","O devedor paga com coisa diferente da devida"],"explicacao":"Art. 360. Transferir o crédito é cessão; pagar com outra coisa é dação em pagamento."},{"id":1695,"materia":"civ","nivel":2,"enunciado":"A doação de todos os bens, sem reserva de renda suficiente para o doador, é:","opcoes":["Nula","Válida","Anulável","Revogável apenas"],"explicacao":"Art. 548 do Código Civil."},{"id":1696,"materia":"civ","nivel":2,"enunciado":"Pródigos, ébrios habituais e viciados em tóxicos são considerados:","opcoes":["Relativamente incapazes","Absolutamente incapazes","Plenamente capazes","Emancipados"],"explicacao":"Art. 4º, II e IV, do Código Civil."},{"id":1697,"materia":"pciv","nivel":2,"enunciado":"A audiência de conciliação do art. 334 deixa de ocorrer quando:","opcoes":["Ambas as partes manifestam desinteresse","Apenas o autor manifesta desinteresse na petição inicial","O juiz estiver de férias","A causa for de pequeno valor"],"explicacao":"Art. 334, § 4º, I. Também quando não se admite autocomposição."},{"id":1698,"materia":"pciv","nivel":2,"enunciado":"A falta injustificada à audiência de conciliação do art. 334 é:","opcoes":["Ato atentatório à dignidade da justiça","Causa de extinção imediata do processo","Confissão ficta de todos os fatos","Ato sem nenhuma consequência"],"explicacao":"Art. 334, § 8º, com multa de até 2% do valor da causa."},{"id":1699,"materia":"pciv","nivel":2,"enunciado":"A reconvenção é:","opcoes":["Ação do réu contra o autor no mesmo processo","Recurso contra a sentença de mérito","Pedido de produção de prova pericial feito pelo réu","Desistência da ação pelo autor"],"explicacao":"Art. 343 do CPC."},{"id":1700,"materia":"pciv","nivel":2,"enunciado":"No CPC de 2015, a reconvenção é apresentada:","opcoes":["Na própria contestação","Em peça separada, 30 dias depois","Somente em grau de recurso","Depois da sentença"],"explicacao":"Art. 343 do CPC."},{"id":1701,"materia":"pciv","nivel":2,"enunciado":"A incompetência absoluta pode ser alegada:","opcoes":["Em qualquer tempo e grau de jurisdição","Só na contestação, sob pena de preclusão","Só no primeiro grau","Só pelo Ministério Público"],"explicacao":"Art. 64, § 1º, do CPC."},{"id":1702,"materia":"pciv","nivel":2,"enunciado":"Se não for alegada em preliminar de contestação, a incompetência relativa:","opcoes":["Prorroga-se","Gera nulidade absoluta","Extingue o processo","Pode ser alegada a qualquer tempo"],"explicacao":"Art. 65 do CPC."},{"id":1703,"materia":"pciv","nivel":2,"enunciado":"A competência territorial é, em regra, competência:","opcoes":["Relativa","Absoluta","Funcional","Material"],"explicacao":"Pode ser modificada por acordo das partes ou prorrogada."},{"id":1704,"materia":"pciv","nivel":2,"enunciado":"Em regra, as ações fundadas em direito real sobre imóveis são propostas no foro:","opcoes":["Da situação da coisa","Do domicílio do autor","Do domicílio do réu","Da capital do estado"],"explicacao":"Art. 47 do CPC."},{"id":1705,"materia":"pciv","nivel":2,"enunciado":"A ação de alimentos é proposta no foro do domicílio:","opcoes":["De quem pede os alimentos","De quem deve pagar","Do advogado do autor, nos termos da procuração","Do Ministério Público"],"explicacao":"Art. 53, II, do CPC."},{"id":1706,"materia":"pciv","nivel":2,"enunciado":"O litisconsórcio em que a decisão deve ser igual para todos é o:","opcoes":["Unitário","Simples","Facultativo","Ativo"],"explicacao":"Art. 116 do CPC."},{"id":1707,"materia":"pciv","nivel":2,"enunciado":"No litisconsórcio necessário, a presença de todos no processo é:","opcoes":["Obrigatória","Facultativa","Proibida","Indiferente"],"explicacao":"Art. 114 do CPC."},{"id":1708,"materia":"pciv","nivel":2,"enunciado":"O assistente simples ingressa no processo para:","opcoes":["Ajudar uma das partes, por ter interesse jurídico","Substituir o autor que desistiu da ação, assumindo o polo ativo","Julgar o processo junto com o juiz","Representar o Ministério Público"],"explicacao":"Art. 119 do CPC."},{"id":1709,"materia":"pciv","nivel":2,"enunciado":"O chamamento ao processo cabe, por exemplo, quando:","opcoes":["O fiador réu chama o devedor principal","O réu chama o vendedor pela evicção","Um terceiro quer ajudar o autor","O juiz chama uma testemunha"],"explicacao":"Art. 130, I. Chamar o vendedor pela evicção é denunciação da lide."},{"id":1710,"materia":"pciv","nivel":2,"enunciado":"O juiz julga antecipadamente o mérito quando:","opcoes":["Não há necessidade de outras provas","As partes ainda não foram citadas","O réu pediu prova pericial ainda não realizada","O autor desistiu da ação"],"explicacao":"Art. 355 do CPC."},{"id":1711,"materia":"pciv","nivel":2,"enunciado":"Na decisão de saneamento e organização do processo, o juiz:","opcoes":["Fixa os pontos controvertidos e as provas","Profere a sentença de mérito e encerra a fase de conhecimento","Cita o réu para contestar","Julga os recursos pendentes"],"explicacao":"Art. 357 do CPC."},{"id":1712,"materia":"pciv","nivel":2,"enunciado":"O juiz julga improcedente o pedido antes de citar o réu, em hipóteses legais. Isso é a:","opcoes":["Improcedência liminar do pedido","Revelia antecipada","Tutela da evidência","Extinção sem mérito"],"explicacao":"Art. 332 do CPC."},{"id":1713,"materia":"pciv","nivel":2,"enunciado":"Em regra, a apelação tem efeito:","opcoes":["Suspensivo","Apenas devolutivo","Nenhum","Translativo apenas"],"explicacao":"Art. 1.012. Há exceções, como na sentença que condena a pagar alimentos."},{"id":1714,"materia":"pciv","nivel":2,"enunciado":"Em regra, o prazo para apresentar contrarrazões a um recurso é de:","opcoes":["15 dias","5 dias","10 dias","30 dias"],"explicacao":"Art. 1.003, § 5º, do CPC, salvo nos embargos de declaração."},{"id":1715,"materia":"trib","nivel":2,"enunciado":"Pelo CTN, a “legislação tributária” compreende leis, tratados, decretos e:","opcoes":["Normas complementares","Sentenças judiciais","Contratos privados","Pareceres de advogados"],"explicacao":"Art. 96 do CTN."},{"id":1716,"materia":"trib","nivel":2,"enunciado":"São normas complementares da legislação tributária, entre outras:","opcoes":["Atos normativos e práticas reiteradas das autoridades","Contratos de compra e venda entre empresas","Decisões judiciais de primeiro grau em casos isolados de contribuintes","Opiniões de professores de direito"],"explicacao":"Art. 100 do CTN."},{"id":1717,"materia":"trib","nivel":2,"enunciado":"A lei que deixa de definir um ato como infração aplica-se a fato passado:","opcoes":["Não definitivamente julgado","Sempre, mesmo já julgado","Nunca, por ser posterior","Só se o contribuinte for primário e de boa-fé"],"explicacao":"Art. 106, II, “a”, do CTN."},{"id":1718,"materia":"trib","nivel":2,"enunciado":"A lei tributária expressamente interpretativa aplica-se a:","opcoes":["Atos ou fatos pretéritos","Apenas fatos futuros","Apenas fatos do mesmo dia","Nenhum fato concreto"],"explicacao":"Art. 106, I, excluída a aplicação de penalidade."},{"id":1719,"materia":"trib","nivel":2,"enunciado":"A capacidade tributária passiva independe da:","opcoes":["Capacidade civil da pessoa","Ocorrência do fato gerador","Existência de lei","Competência do ente"],"explicacao":"Art. 126 do CTN."},{"id":1720,"materia":"trib","nivel":2,"enunciado":"Sem eleição de domicílio, o domicílio tributário da pessoa natural é:","opcoes":["Sua residência habitual","O local de nascimento","O endereço do contador responsável pela declaração","A capital do estado"],"explicacao":"Art. 127, I, do CTN."},{"id":1721,"materia":"trib","nivel":2,"enunciado":"São solidariamente obrigadas as pessoas que tenham:","opcoes":["Interesse comum no fato gerador","Parentesco com o contribuinte","Conta conjunta no mesmo banco que o contribuinte","Domicílio no mesmo município"],"explicacao":"Art. 124, I, do CTN."},{"id":1722,"materia":"trib","nivel":2,"enunciado":"Em regra, a responsabilidade por infração à legislação tributária:","opcoes":["Independe da intenção do agente","Exige prova de dolo","Exige prova de culpa grave ou de intenção de fraudar","Depende de condenação penal"],"explicacao":"Art. 136 do CTN."},{"id":1723,"materia":"trib","nivel":2,"enunciado":"A moratória é:","opcoes":["A prorrogação do prazo de pagamento","O perdão total do crédito concedido por lei específica","A extinção pelo pagamento","A anulação do lançamento"],"explicacao":"Suspende a exigibilidade do crédito (art. 151, I)."},{"id":1724,"materia":"trib","nivel":2,"enunciado":"A remissão é:","opcoes":["O perdão do crédito tributário","A prorrogação do prazo de pagamento","O parcelamento da dívida","A suspensão da exigibilidade"],"explicacao":"Extingue o crédito (art. 156, IV)."},{"id":1725,"materia":"trib","nivel":2,"enunciado":"A transação tributária:","opcoes":["Extingue o crédito por concessões mútuas","Suspende o crédito enquanto durar o processo judicial","Exclui o crédito por lei especial","Cria um novo crédito tributário"],"explicacao":"Art. 171 do CTN."},{"id":1726,"materia":"trib","nivel":2,"enunciado":"A consignação em pagamento julgada procedente:","opcoes":["Extingue o crédito","Suspende o crédito","Exclui o crédito","Não tem efeito"],"explicacao":"Art. 156, VIII, do CTN."},{"id":1727,"materia":"trib","nivel":2,"enunciado":"Se a lei não fixar data, o tributo vence:","opcoes":["30 dias após a notificação do lançamento","No mesmo dia do fato gerador","90 dias após a publicação da lei que instituiu o tributo","No fim do exercício financeiro"],"explicacao":"Art. 160 do CTN."},{"id":1728,"materia":"trib","nivel":2,"enunciado":"Se a lei não dispuser de outro modo, os juros de mora no CTN são de:","opcoes":["1% ao mês","2% ao mês","0,5% ao mês","1% ao ano"],"explicacao":"Art. 161, § 1º, do CTN."},{"id":1729,"materia":"trib","nivel":2,"enunciado":"O direito de pedir a restituição de tributo pago indevidamente se extingue em:","opcoes":["5 anos","2 anos","10 anos","1 ano"],"explicacao":"Art. 168 do CTN."},{"id":1730,"materia":"trib","nivel":2,"enunciado":"A certidão positiva com efeito de negativa é emitida quando o crédito está:","opcoes":["Não vencido, garantido ou suspenso","Vencido e sem garantia","Inscrito e prescrito","Em cobrança judicial sem garantia nem penhora"],"explicacao":"Art. 206 do CTN."},{"id":1731,"materia":"trib","nivel":2,"enunciado":"As contribuições sociais para a seguridade social obedecem à anterioridade:","opcoes":["Nonagesimal apenas","Anual apenas","Anual e nonagesimal","Nenhuma delas"],"explicacao":"Art. 195, § 6º, da Constituição."},{"id":1732,"materia":"trib","nivel":2,"enunciado":"A contribuição para o custeio da iluminação pública é de competência:","opcoes":["Dos municípios e do DF","Dos estados","Da União","Das concessionárias"],"explicacao":"Art. 149-A da Constituição."},{"id":1733,"materia":"afo","nivel":2,"enunciado":"Pela LRF, a LDO deve trazer, entre outros, o Anexo de:","opcoes":["Metas Fiscais","Obras Concluídas","Servidores Ativos","Contratos Privados"],"explicacao":"Art. 4º, § 1º. Também o Anexo de Riscos Fiscais."},{"id":1734,"materia":"afo","nivel":2,"enunciado":"O Anexo de Riscos Fiscais da LDO avalia:","opcoes":["Passivos contingentes e outros riscos","O número de servidores aposentados","A arrecadação prevista de cada município do estado","Os salários dos parlamentares"],"explicacao":"Art. 4º, § 3º, da LRF."},{"id":1735,"materia":"afo","nivel":2,"enunciado":"A reserva de contingência serve para atender:","opcoes":["Passivos contingentes e eventos imprevistos","Aumentos salariais já previstos","Pagamento de juros e encargos da dívida mobiliária","Despesas de publicidade oficial"],"explicacao":"Art. 5º, III, da LRF."},{"id":1736,"materia":"afo","nivel":2,"enunciado":"Na classificação funcional da despesa, o nível mais agregado é a:","opcoes":["Função","Subfunção","Ação","Categoria econômica"],"explicacao":"Ex.: saúde, educação, segurança pública."},{"id":1737,"materia":"afo","nivel":2,"enunciado":"Pela categoria econômica, a despesa se divide em:","opcoes":["Corrente e de capital","Fixa e variável","Federal e estadual","Prevista e realizada"],"explicacao":"Lei 4.320/1964, art. 12."},{"id":1738,"materia":"afo","nivel":2,"enunciado":"Os grupos de natureza de despesa incluem pessoal, juros, outras correntes, investimentos, inversões financeiras e:","opcoes":["Amortização da dívida","Receita tributária","Restos a pagar","Reserva legal"],"explicacao":"São seis grupos."},{"id":1739,"materia":"afo","nivel":2,"enunciado":"A compra de um imóvel que já está em uso é classificada como:","opcoes":["Inversão financeira","Investimento","Despesa corrente","Transferência corrente"],"explicacao":"Art. 12, § 5º, I, da Lei 4.320/1964."},{"id":1740,"materia":"afo","nivel":2,"enunciado":"No orçamento, o programa é:","opcoes":["O instrumento que organiza a ação para um objetivo","O valor total da despesa de pessoal","A receita prevista para o ano","O relatório de gestão fiscal publicado a cada quadrimestre"],"explicacao":"Articula um conjunto de ações."},{"id":1741,"materia":"afo","nivel":2,"enunciado":"A atividade orçamentária é uma ação realizada de modo:","opcoes":["Contínuo e permanente","Limitado no tempo","Eventual e único","Exclusivo de investimentos"],"explicacao":"Ex.: manutenção de escolas."},{"id":1742,"materia":"afo","nivel":2,"enunciado":"O projeto orçamentário é uma ação:","opcoes":["Limitada no tempo, que gera um produto","Contínua e permanente","Sem produto definido","Ligada só à dívida"],"explicacao":"Ex.: construção de um hospital."},{"id":1743,"materia":"afo","nivel":2,"enunciado":"A operação especial é uma ação que:","opcoes":["Não gera bem ou serviço, como pagar dívidas","Constrói novas obras públicas","Mantém serviços já existentes e gera produto contínuo","Contrata novos servidores"],"explicacao":"Ex.: amortização da dívida e transferências."},{"id":1744,"materia":"afo","nivel":2,"enunciado":"São receitas extraorçamentárias, por exemplo:","opcoes":["Cauções e depósitos de terceiros","Impostos e taxas arrecadados","Alienação de bens públicos","Operações de crédito"],"explicacao":"Não pertencem ao ente; serão devolvidas."},{"id":1745,"materia":"afo","nivel":2,"enunciado":"Pela Lei 4.320/1964, a realização de despesa sem prévio empenho é:","opcoes":["Vedada","Permitida em qualquer caso","Permitida até R$ 10 mil","Permitida no fim do ano"],"explicacao":"Art. 60 da Lei 4.320/1964."},{"id":1746,"materia":"afo","nivel":2,"enunciado":"O empenho por estimativa é usado para despesas:","opcoes":["Cujo valor exato não se pode prever","De valor fixo, pagas de uma vez","De valor fixo e conhecido, pagas em parcelas mensais","De pessoal efetivo"],"explicacao":"Ex.: contas de água e energia."},{"id":1747,"materia":"afo","nivel":2,"enunciado":"O empenho global é usado para despesas:","opcoes":["Contratuais, de valor certo e parceladas","De valor impossível de prever","De pronto pagamento","De restos a pagar"],"explicacao":"Ex.: aluguel com valor fixo mensal."},{"id":1748,"materia":"afo","nivel":2,"enunciado":"O suprimento de fundos (adiantamento) serve para:","opcoes":["Despesas que não podem esperar o processo normal","Pagar salários de todos os servidores","Investimentos em obras de grande porte planejadas no PPA","Amortizar a dívida pública"],"explicacao":"Art. 68 da Lei 4.320/1964."},{"id":1749,"materia":"afo","nivel":2,"enunciado":"Pela LRF, a operação de crédito por antecipação de receita (ARO) deve ser liquidada até:","opcoes":["10 de dezembro do mesmo ano","31 de dezembro do mesmo ano","30 de junho do ano seguinte","O fim do mandato"],"explicacao":"Art. 38, II, da LRF."},{"id":1750,"materia":"afo","nivel":2,"enunciado":"Pela LRF, a operação por antecipação de receita (ARO) é proibida:","opcoes":["No último ano de mandato","No primeiro ano de mandato","Em anos sem eleição","Em qualquer ano par"],"explicacao":"Art. 38, IV, “b”, da LRF."},{"id":1751,"materia":"gest","nivel":2,"enunciado":"Burns e Stalker classificaram as organizações em:","opcoes":["Mecanísticas e orgânicas","Públicas e privadas","Grandes e pequenas","Formais e informais"],"explicacao":"As orgânicas se adaptam melhor a ambientes instáveis."},{"id":1752,"materia":"gest","nivel":2,"enunciado":"Entre as cinco partes da organização descritas por Mintzberg estão:","opcoes":["Cúpula estratégica e núcleo operacional","Missão, visão e valores institucionais declarados","Receita e despesa do ano","Clientes e fornecedores"],"explicacao":"Também linha intermediária, tecnoestrutura e assessoria de apoio."},{"id":1753,"materia":"gest","nivel":2,"enunciado":"A teoria da expectância (expectativa) da motivação é de:","opcoes":["Vroom","Maslow","Taylor","Weber"],"explicacao":"Motivação = expectativa × instrumentalidade × valência."},{"id":1754,"materia":"gest","nivel":2,"enunciado":"A teoria das necessidades de realização, afiliação e poder é de:","opcoes":["McClelland","Herzberg","McGregor","Fayol"],"explicacao":"São necessidades adquiridas ao longo da vida."},{"id":1755,"materia":"gest","nivel":2,"enunciado":"A teoria ERC (existência, relacionamento e crescimento) é de:","opcoes":["Alderfer","Maslow","Vroom","Likert"],"explicacao":"Reformula a pirâmide de Maslow em três níveis."},{"id":1756,"materia":"gest","nivel":2,"enunciado":"A liderança transformacional se caracteriza por:","opcoes":["Inspirar e mudar os valores dos liderados","Trocar recompensas por desempenho, em acordos claros com a equipe","Decidir tudo sozinho, sem consulta","Deixar o grupo decidir tudo"],"explicacao":"Busca engajar a equipe numa visão comum."},{"id":1757,"materia":"gest","nivel":2,"enunciado":"A liderança transacional se baseia em:","opcoes":["Troca de recompensas por desempenho","Inspiração e carisma do líder, que transforma valores","Ausência total de controle","Decisões tomadas em votação"],"explicacao":"Recompensa e punição conforme o resultado."},{"id":1758,"materia":"gest","nivel":2,"enunciado":"O grid gerencial de Blake e Mouton combina a preocupação com as pessoas e com a:","opcoes":["Produção","Hierarquia","Tecnologia","Concorrência"],"explicacao":"É uma grade de 9 × 9."},{"id":1759,"materia":"gest","nivel":2,"enunciado":"No grid gerencial, o estilo 9.9 corresponde ao gerente:","opcoes":["De equipe","Empobrecido","De clube de campo","Autoritário"],"explicacao":"Alta preocupação com pessoas e com produção."},{"id":1760,"materia":"gest","nivel":2,"enunciado":"A departamentalização por clientes agrupa as atividades conforme:","opcoes":["O público atendido","A localização geográfica","As etapas do processo","Os produtos fabricados"],"explicacao":"Ex.: atendimento a pessoa física e a pessoa jurídica."},{"id":1761,"materia":"gest","nivel":2,"enunciado":"A gestão da qualidade total (TQM) busca:","opcoes":["Melhoria contínua com todos envolvidos","Fiscalização só no fim do processo","Redução de salários em toda a empresa","Centralização de todas as decisões na alta direção"],"explicacao":"A qualidade é responsabilidade de todos."},{"id":1762,"materia":"gest","nivel":2,"enunciado":"O termo japonês kaizen significa:","opcoes":["Melhoria contínua","Estoque zero","Controle visual","Trabalho em equipe"],"explicacao":"Pequenas melhorias constantes."},{"id":1763,"materia":"gest","nivel":2,"enunciado":"O just in time busca:","opcoes":["Produzir no momento certo, com pouco estoque","Produzir o máximo possível de uma vez","Estocar grandes lotes para evitar qualquer falta de material","Terceirizar toda a produção"],"explicacao":"Nasceu no sistema Toyota."},{"id":1764,"materia":"gest","nivel":2,"enunciado":"A reengenharia propõe:","opcoes":["Redesenho radical dos processos","Pequenas melhorias graduais","Aumento de níveis hierárquicos","Manutenção dos processos atuais"],"explicacao":"Hammer e Champy, anos 1990."},{"id":1765,"materia":"gest","nivel":2,"enunciado":"O downsizing consiste em:","opcoes":["Reduzir níveis hierárquicos e pessoal","Aumentar a estrutura da organização","Abrir novas filiais pelo país","Contratar mais gerentes"],"explicacao":"Busca uma estrutura mais enxuta."},{"id":1766,"materia":"gest","nivel":2,"enunciado":"O governo eletrônico tem como objetivo principal:","opcoes":["Prestar serviços públicos por meios digitais","Substituir todos os servidores por robôs","Eliminar o atendimento ao cidadão","Restringir o acesso à informação a quem tem certificado digital"],"explicacao":"Ex.: serviços no portal gov.br."},{"id":1767,"materia":"gest","nivel":2,"enunciado":"A Carta de Serviços ao Usuário está prevista na Lei:","opcoes":["13.460/2017","12.527/2011","8.112/1990","14.133/2021"],"explicacao":"É o Código de Defesa do Usuário do Serviço Público."},{"id":1768,"materia":"gest","nivel":2,"enunciado":"Pela Lei 13.460/2017, as ouvidorias públicas recebem:","opcoes":["Reclamações, denúncias e sugestões","Apenas pedidos de emprego","Somente processos judiciais","Apenas pagamentos de tributos"],"explicacao":"Também elogios e solicitações."},{"id":1769,"materia":"arq","nivel":2,"enunciado":"A classificação de documentos consiste em:","opcoes":["Agrupá-los segundo um plano de classificação","Eliminá-los depois de 5 anos de guarda","Digitalizá-los na ordem de chegada ao protocolo central","Colocá-los em caixas por cor"],"explicacao":"Deve ocorrer desde a produção do documento."},{"id":1770,"materia":"arq","nivel":2,"enunciado":"O plano de classificação organiza os documentos conforme:","opcoes":["As funções e atividades do órgão","A cor e o tamanho das pastas","O nome do servidor que arquivou","A data em que foram digitalizados"],"explicacao":"Reflete o que o órgão faz."},{"id":1771,"materia":"arq","nivel":2,"enunciado":"As atividades-meio de um órgão são as:","opcoes":["De apoio, como pessoal e material","Ligadas à missão principal","De atendimento ao público","De julgamento de processos"],"explicacao":"Existem em praticamente todos os órgãos."},{"id":1772,"materia":"arq","nivel":2,"enunciado":"As atividades-fim de um órgão são as:","opcoes":["Ligadas à sua missão principal","De apoio administrativo","De compra de material","De gestão de pessoal"],"explicacao":"Variam conforme o órgão."},{"id":1773,"materia":"arq","nivel":2,"enunciado":"Na tabela de temporalidade, a destinação final pode ser:","opcoes":["Eliminação ou guarda permanente","Venda ou doação a terceiros","Publicação ou sigilo eterno","Digitalização ou incineração livre"],"explicacao":"Definida após a avaliação."},{"id":1774,"materia":"arq","nivel":2,"enunciado":"O acondicionamento de documentos consiste em:","opcoes":["Embalá-los para protegê-los","Classificá-los por assunto","Eliminá-los após o prazo","Registrá-los no protocolo"],"explicacao":"Ex.: pastas e caixas adequadas."},{"id":1775,"materia":"arq","nivel":2,"enunciado":"O armazenamento de documentos consiste em:","opcoes":["Guardá-los em mobiliário e local adequados","Embalá-los em pastas e envelopes","Classificá-los conforme o plano","Avaliá-los para definir prazos de guarda e eliminação"],"explicacao":"Envolve estantes, arquivos e condições ambientais."},{"id":1776,"materia":"arq","nivel":2,"enunciado":"A gestão eletrônica de documentos (GED) visa:","opcoes":["Gerenciar documentos em meio digital","Imprimir todos os documentos","Proibir documentos em papel","Eliminar documentos antigos"],"explicacao":"Inclui captura, indexação, armazenamento e recuperação."},{"id":1777,"materia":"arq","nivel":2,"enunciado":"O SIGAD é um:","opcoes":["Sistema de gestão arquivística de documentos","Sindicato de arquivistas do Brasil","Selo de garantia de documentos","Sistema de geração de documentos"],"explicacao":"Deve seguir os requisitos do e-ARQ Brasil."},{"id":1778,"materia":"arq","nivel":2,"enunciado":"O e-ARQ Brasil estabelece:","opcoes":["Requisitos para sistemas de gestão arquivística","Regras de acesso à informação pública","Normas para arquivos de bibliotecas","Prazos para eliminação de documentos"],"explicacao":"Aprovado pelo CONARQ."},{"id":1779,"materia":"arq","nivel":2,"enunciado":"Metadados são:","opcoes":["Dados que descrevem outros dados","Documentos que perderam o valor","Cópias de segurança dos arquivos","Arquivos maiores que 1 GB"],"explicacao":"Ex.: autor, data e assunto de um documento."},{"id":1780,"materia":"arq","nivel":2,"enunciado":"A Lei 12.682/2012 trata da:","opcoes":["Digitalização e armazenamento eletrônico de documentos","Política nacional de arquivos públicos e privados","Classificação de informações sigilosas do governo federal e dos estados","Criação do Conselho Nacional de Arquivos"],"explicacao":"Alterada pela Lei 13.874/2019."},{"id":1781,"materia":"arq","nivel":2,"enunciado":"Pela Lei de Acesso à Informação, o pedido deve ser respondido em até:","opcoes":["20 dias, prorrogáveis por mais 10","10 dias, improrrogáveis","30 dias, prorrogáveis por mais 30","5 dias úteis"],"explicacao":"Art. 11, §§ 1º e 2º, da Lei 12.527/2011."},{"id":1782,"materia":"arq","nivel":2,"enunciado":"Pela Lei de Acesso à Informação, informações pessoais ligadas à intimidade ficam restritas por até:","opcoes":["100 anos","25 anos","50 anos","15 anos"],"explicacao":"Art. 31, § 1º, I."},{"id":1783,"materia":"arq","nivel":2,"enunciado":"Pela Lei de Acesso à Informação, quem pede informação:","opcoes":["Não precisa apresentar os motivos","Precisa justificar o interesse e indicar a finalidade do pedido","Precisa ser servidor público","Precisa ter advogado"],"explicacao":"Art. 10, § 3º."},{"id":1784,"materia":"arq","nivel":2,"enunciado":"A massa documental acumulada é formada por documentos:","opcoes":["Acumulados sem tratamento técnico","Já classificados e avaliados","Recolhidos ao arquivo permanente","Digitalizados com metadados"],"explicacao":"Exige diagnóstico antes de ser tratada."},{"id":1785,"materia":"arq","nivel":2,"enunciado":"O conceito de ciclo vital dos documentos corresponde à teoria:","opcoes":["Das três idades","Da proveniência","Da ordem original","Da organicidade"],"explicacao":"Corrente, intermediária e permanente."},{"id":1786,"materia":"arq","nivel":2,"enunciado":"Pelo princípio da organicidade, os documentos:","opcoes":["Refletem a estrutura e as funções do órgão","Devem ficar em ordem alfabética, pelo nome do interessado","Devem ser eliminados após 5 anos","Pertencem ao servidor que os criou"],"explicacao":"Os documentos de arquivo se relacionam entre si."},{"id":1787,"materia":"civ","nivel":3,"enunciado":"O prazo decadencial para anular negócio jurídico por erro ou dolo é de:","opcoes":["4 anos, contados da celebração do negócio","2 anos, contados da celebração do negócio","10 anos, contados do conhecimento do vício","1 ano, contado da descoberta do erro"],"explicacao":"Art. 178, II: no erro, dolo, fraude contra credores, estado de perigo e lesão, 4 anos do dia do negócio."},{"id":1788,"materia":"civ","nivel":3,"enunciado":"Quando a lei diz que um ato é anulável mas não fixa prazo, a anulação deve ser pedida em:","opcoes":["2 anos, a contar da conclusão do ato","4 anos, a contar da conclusão do ato","5 anos, a contar do conhecimento do vício","10 anos, como na prescrição geral"],"explicacao":"Art. 179 do Código Civil."},{"id":1789,"materia":"civ","nivel":3,"enunciado":"Há lesão (art. 157) quando alguém, por premente necessidade ou inexperiência:","opcoes":["Assume prestação manifestamente desproporcional","É ameaçado de dano grave à sua família","É induzido em erro por artifício da outra parte","Firma contrato sem a forma que a lei exige"],"explicacao":"A lesão é o desequilíbrio entre as prestações nascido da necessidade ou inexperiência."},{"id":1790,"materia":"civ","nivel":3,"enunciado":"No estado de perigo (art. 156), a pessoa assume obrigação excessivamente onerosa para:","opcoes":["Salvar-se, ou a alguém da família, de grave dano","Fugir de dívidas com outros credores anteriores ao negócio","Obter lucro rápido em operação especulativa","Cumprir ordem de autoridade pública competente"],"explicacao":"O grave dano precisa ser conhecido pela outra parte."},{"id":1791,"materia":"civ","nivel":3,"enunciado":"O negócio praticado em fraude contra credores é:","opcoes":["Anulável","Nulo","Inexistente","Válido e eficaz"],"explicacao":"Art. 171, II. Anula-se por ação pauliana."},{"id":1792,"materia":"civ","nivel":3,"enunciado":"Pelo Código Civil, o negócio jurídico nulo:","opcoes":["Não convalesce pelo decurso do tempo","Convalida-se após 4 anos sem impugnação","Pode ser confirmado pelas partes a qualquer tempo","Só pode ser alegado pela parte prejudicada"],"explicacao":"Art. 169: o nulo não é suscetível de confirmação nem convalesce com o tempo."},{"id":1793,"materia":"civ","nivel":3,"enunciado":"Pela teoria da imprevisão (art. 478), o devedor pode pedir a resolução do contrato quando a prestação se torna:","opcoes":["Excessivamente onerosa por fato extraordinário e imprevisível","Um pouco mais cara por causa da inflação normal","Desinteressante por mudança de planos pessoais","Impossível por culpa exclusiva do próprio devedor, após a assinatura"],"explicacao":"Vale para contratos de execução continuada ou diferida, com extrema vantagem para a outra parte."},{"id":1794,"materia":"civ","nivel":3,"enunciado":"A exceção do contrato não cumprido (art. 476) significa que, nos contratos bilaterais:","opcoes":["Ninguém exige a prestação do outro antes de cumprir a sua","O credor pode rescindir o contrato sem aviso prévio","O devedor fica dispensado se o preço aumentar","O contrato se extingue com a morte de qualquer das partes contratantes"],"explicacao":"É a exceptio non adimpleti contractus."},{"id":1795,"materia":"civ","nivel":3,"enunciado":"Nas arras confirmatórias, se quem as deu desiste do contrato:","opcoes":["Perde-as em favor da outra parte","Recebe-as de volta em dobro","Recebe-as de volta sem correção","Elas viram pagamento do preço total"],"explicacao":"Art. 418. Se quem recebeu desistir, devolve-as mais o equivalente."},{"id":1796,"materia":"civ","nivel":3,"enunciado":"O direito real de superfície permite ao proprietário conceder a outrem o direito de:","opcoes":["Construir ou plantar em seu terreno, por tempo determinado","Morar no imóvel de graça durante toda a vida","Passar pelo terreno para chegar à via pública","Receber os frutos do imóvel como garantia de dívida do proprietário"],"explicacao":"Art. 1.369, por escritura pública registrada."},{"id":1797,"materia":"civ","nivel":3,"enunciado":"O usufruto é o direito real de:","opcoes":["Usar e perceber os frutos de coisa alheia","Morar em imóvel emprestado por contrato","Reter bem móvel entregue pelo devedor como garantia","Preferir na compra do imóvel alugado"],"explicacao":"O usufrutuário usa e frui; o nu-proprietário mantém a propriedade."},{"id":1798,"materia":"civ","nivel":3,"enunciado":"O penhor comum recai, em regra, sobre:","opcoes":["Bem móvel, com a posse entregue ao credor","Bem imóvel, registrado no cartório de imóveis","Frutos futuros de uma plantação arrendada","Créditos trabalhistas do próprio devedor"],"explicacao":"Art. 1.431. Há penhores especiais (rural, industrial) em que a posse fica com o devedor."},{"id":1799,"materia":"civ","nivel":3,"enunciado":"A usucapião ordinária de imóvel exige 10 anos de posse, além de:","opcoes":["Justo título e boa-fé","Área de até 250 m²","Uso para moradia da família","Não ter outro imóvel"],"explicacao":"Art. 1.242. O prazo cai para 5 anos em certos casos de aquisição onerosa registrada."},{"id":1800,"materia":"civ","nivel":3,"enunciado":"A usucapião familiar (art. 1.240-A) exige posse direta e exclusiva por:","opcoes":["2 anos, de imóvel urbano abandonado pelo ex-cônjuge","5 anos, de imóvel rural de até 50 hectares","10 anos, de qualquer imóvel com justo título e boa-fé do possuidor","15 anos, independentemente de boa-fé"],"explicacao":"Imóvel urbano de até 250 m², usado como moradia."},{"id":1801,"materia":"civ","nivel":3,"enunciado":"Sem descendentes nem ascendentes, a herança é deferida:","opcoes":["Por inteiro ao cônjuge sobrevivente","Aos colaterais, junto com o cônjuge","Ao município, como herança jacente","Metade ao cônjuge e metade aos irmãos"],"explicacao":"Art. 1.838 do Código Civil."},{"id":1802,"materia":"civ","nivel":3,"enunciado":"Na sucessão legítima, os parentes colaterais herdam até o:","opcoes":["Quarto grau","Terceiro grau","Segundo grau","Sexto grau"],"explicacao":"Art. 1.839. Primos são colaterais de 4º grau."},{"id":1803,"materia":"civ","nivel":3,"enunciado":"O testamento particular deve ser lido e assinado por quem o escreveu diante de, no mínimo:","opcoes":["3 testemunhas","2 testemunhas","5 testemunhas","1 tabelião e 1 testemunha"],"explicacao":"Art. 1.876 do Código Civil."},{"id":1804,"materia":"civ","nivel":3,"enunciado":"A responsabilidade do dono ou detentor de animal pelo dano que ele causar:","opcoes":["É objetiva, salvo culpa da vítima ou força maior","Depende sempre de prova de culpa do dono","Só existe se o animal for de raça perigosa","Recai apenas sobre quem o guardava na hora do fato danoso"],"explicacao":"Art. 936 do Código Civil."},{"id":1805,"materia":"pciv","nivel":3,"enunciado":"Pelo CPC, depois de oferecida a contestação, a desistência da ação depende de:","opcoes":["Consentimento do réu","Autorização do Ministério Público","Pagamento prévio das custas finais","Decisão do tribunal de segunda instância"],"explicacao":"Art. 485, § 4º, do CPC."},{"id":1806,"materia":"pciv","nivel":3,"enunciado":"Entre 20 de dezembro e 20 de janeiro, os prazos processuais:","opcoes":["Ficam suspensos","Correm normalmente","São contados em dobro","São interrompidos e reiniciados"],"explicacao":"Art. 220 do CPC."},{"id":1807,"materia":"pciv","nivel":3,"enunciado":"Qual destas é hipótese de IMPEDIMENTO do juiz (art. 144)?","opcoes":["Seu cônjuge atua como advogado da parte","Ser amigo íntimo de uma das partes","Ser credor de uma das partes","Ter aconselhado alguma das partes sobre o objeto da causa"],"explicacao":"As demais são hipóteses de suspeição (art. 145)."},{"id":1808,"materia":"pciv","nivel":3,"enunciado":"Pelo princípio da não surpresa (art. 10), o juiz:","opcoes":["Não decide com base em fundamento que as partes não puderam discutir","Não pode julgar matéria de ordem pública de ofício","Deve decidir sempre conforme a jurisprudência","Precisa avisar as partes da data da sentença"],"explicacao":"Vale até para matérias que o juiz pode conhecer de ofício."},{"id":1809,"materia":"pciv","nivel":3,"enunciado":"Quando a gratuidade da justiça é pedida por pessoa natural:","opcoes":["Presume-se verdadeira a alegação de insuficiência","Exige prova documental de renda zero","Só é concedida a quem tem defensor público","Depende de parecer prévio do Ministério Público sobre a renda"],"explicacao":"Art. 99, § 3º, do CPC."},{"id":1810,"materia":"pciv","nivel":3,"enunciado":"A petição inicial será indeferida, entre outros casos, quando:","opcoes":["For inepta","O réu for revel","Houver pedido de tutela de urgência","Houver litisconsórcio passivo"],"explicacao":"Art. 330 do CPC."},{"id":1811,"materia":"pciv","nivel":3,"enunciado":"Se a petição inicial tiver defeito sanável, o juiz manda o autor emendá-la em:","opcoes":["15 dias","5 dias","10 dias","30 dias"],"explicacao":"Art. 321 do CPC."},{"id":1812,"materia":"pciv","nivel":3,"enunciado":"Após a citação, o autor só pode alterar o pedido ou a causa de pedir:","opcoes":["Com o consentimento do réu, até o saneamento","Livremente, até a sentença, sem ouvir a parte contrária","Em nenhuma hipótese","Com autorização do MP"],"explicacao":"Art. 329, II, do CPC."},{"id":1813,"materia":"pciv","nivel":3,"enunciado":"A tutela antecipada requerida em caráter antecedente se estabiliza quando:","opcoes":["Não se interpõe recurso contra a decisão que a concede","O juiz profere sentença de mérito","O autor adita a petição inicial","O réu apresenta contestação no prazo legal, sem pedir provas"],"explicacao":"Art. 304 do CPC."},{"id":1814,"materia":"pciv","nivel":3,"enunciado":"Para rever, reformar ou invalidar a tutela antecipada estabilizada, a ação deve ser proposta em:","opcoes":["2 anos","5 anos","1 ano","120 dias"],"explicacao":"Art. 304, § 5º, contados da ciência da decisão que extinguiu o processo."},{"id":1815,"materia":"pciv","nivel":3,"enunciado":"A distribuição dinâmica do ônus da prova (art. 373, § 1º) permite ao juiz:","opcoes":["Atribuir o ônus de modo diverso, em decisão fundamentada","Dispensar toda prova nos processos de família","Inverter o ônus só na sentença, sem nenhum aviso prévio às partes","Transferir o ônus da prova ao Ministério Público"],"explicacao":"A parte deve ter oportunidade de se desincumbir do ônus atribuído."},{"id":1816,"materia":"pciv","nivel":3,"enunciado":"Pelo CPC, o número de testemunhas arroladas por cada parte não pode passar de:","opcoes":["10, sendo 3 para cada fato","5, sendo no máximo 2 para cada fato","3, sem limite por fato","8, sendo 4 para cada fato"],"explicacao":"Art. 357, § 6º."},{"id":1817,"materia":"pciv","nivel":3,"enunciado":"O agravo interno cabe contra:","opcoes":["Decisão do relator, para o órgão colegiado","Sentença de primeiro grau, em 5 dias","Despacho de mero expediente do juiz","Acórdão do tribunal, dirigido diretamente ao STF"],"explicacao":"Art. 1.021 do CPC; prazo de 15 dias."},{"id":1818,"materia":"pciv","nivel":3,"enunciado":"No recurso extraordinário, o recorrente deve demonstrar:","opcoes":["A repercussão geral da questão constitucional","Divergência entre tribunais estaduais","Violação a lei federal infraconstitucional pelo acórdão","Esgotamento das vias administrativas"],"explicacao":"Art. 102, § 3º, da CF."},{"id":1819,"materia":"pciv","nivel":3,"enunciado":"A ação monitória pode ser proposta por quem tem:","opcoes":["Prova escrita sem eficácia de título executivo","Título executivo extrajudicial já vencido e não pago pelo devedor","Sentença transitada em julgado","Apenas prova testemunhal do crédito"],"explicacao":"Art. 700 do CPC."},{"id":1820,"materia":"pciv","nivel":3,"enunciado":"A impenhorabilidade dos salários não vale quando a execução é para pagar:","opcoes":["Prestação alimentícia","Dívida de condomínio","Tributo municipal","Empréstimo bancário consignado"],"explicacao":"Art. 833, § 2º. Também não vale para o que exceder 50 salários mínimos mensais."},{"id":1821,"materia":"pciv","nivel":3,"enunciado":"Na execução, os embargos de terceiro podem ser opostos até:","opcoes":["5 dias após a arrematação, antes da assinatura da carta","15 dias após a citação do executado","A sentença que extingue a execução","30 dias após a penhora do bem"],"explicacao":"Art. 675 do CPC. Vale também para adjudicação e alienação por iniciativa particular."},{"id":1822,"materia":"pciv","nivel":3,"enunciado":"Contra a decisão que julga a liquidação de sentença cabe:","opcoes":["Agravo de instrumento","Apelação","Embargos de declaração apenas","Recurso ordinário"],"explicacao":"Art. 1.015, parágrafo único, do CPC."},{"id":1823,"materia":"trib","nivel":3,"enunciado":"A simples atualização monetária da base de cálculo de um tributo pode ser feita por:","opcoes":["Decreto, sem superar o índice oficial","Portaria do secretário de Fazenda, em qualquer percentual","Resolução do Senado Federal apenas","Somente lei complementar"],"explicacao":"Art. 97, § 2º, do CTN e Súmula 160 do STJ."},{"id":1824,"materia":"trib","nivel":3,"enunciado":"Pelo CTN, a natureza jurídica específica do tributo é dada:","opcoes":["Pelo fato gerador da obrigação","Pelo destino legal da arrecadação","Pelo nome que a lei dá ao tributo","Pelo ente que faz a arrecadação"],"explicacao":"Art. 4º do CTN."},{"id":1825,"materia":"trib","nivel":3,"enunciado":"Pelo simples fato de não ser cumprida, a obrigação acessória:","opcoes":["Converte-se em principal quanto à multa","Extingue-se sem qualquer consequência","Vira crime contra a ordem tributária","Suspende o crédito tributário principal"],"explicacao":"Art. 113, § 3º, do CTN."},{"id":1826,"materia":"trib","nivel":3,"enunciado":"Pelo art. 118 do CTN, a definição do fato gerador é interpretada:","opcoes":["Abstraindo-se da validade jurídica dos atos praticados","Conforme a licitude da atividade exercida","Apenas segundo a forma do contrato firmado entre as partes envolvidas","De modo sempre favorável ao contribuinte"],"explicacao":"É o princípio do pecunia non olet: renda de atividade ilícita também é tributada."},{"id":1827,"materia":"trib","nivel":3,"enunciado":"Quem adquire fundo de comércio e continua a atividade responde INTEGRALMENTE pelos tributos se o alienante:","opcoes":["Cessar a exploração do comércio","Prosseguir na atividade em outro ramo","Iniciar nova atividade em até 6 meses","For pessoa física sem outros bens"],"explicacao":"Art. 133, I. Nos outros dois casos, a responsabilidade é subsidiária."},{"id":1828,"materia":"trib","nivel":3,"enunciado":"Pelo art. 135 do CTN, diretores e gerentes respondem pessoalmente por créditos resultantes de atos praticados com:","opcoes":["Excesso de poderes ou infração de lei","Simples inadimplemento do tributo pela pessoa jurídica","Prejuízo contábil no exercício","Atraso na entrega de declarações"],"explicacao":"A Súmula 430 do STJ diz que o mero inadimplemento não gera essa responsabilidade."},{"id":1829,"materia":"trib","nivel":3,"enunciado":"Pela Súmula 435 do STJ, presume-se dissolvida irregularmente a empresa que:","opcoes":["Deixa de funcionar no domicílio fiscal sem avisar os órgãos","Tem débitos tributários vencidos há mais de 5 anos","Teve a falência decretada pelo juiz","Não distribuiu lucros aos sócios"],"explicacao":"Isso autoriza redirecionar a execução fiscal ao sócio-gerente."},{"id":1830,"materia":"trib","nivel":3,"enunciado":"Salvo disposição de lei em contrário, o parcelamento do crédito tributário NÃO exclui:","opcoes":["Juros e multas","O crédito principal","A suspensão do crédito","A inscrição em dívida ativa"],"explicacao":"Art. 155-A, § 1º, do CTN."},{"id":1831,"materia":"trib","nivel":3,"enunciado":"Qual destas NÃO suspende a exigibilidade do crédito tributário?","opcoes":["Anistia","Moratória","Depósito do montante integral","Liminar em mandado de segurança"],"explicacao":"A anistia exclui o crédito (art. 175)."},{"id":1832,"materia":"trib","nivel":3,"enunciado":"A prescrição da cobrança do crédito tributário é interrompida, entre outros, pelo:","opcoes":["Despacho do juiz que ordena a citação na execução fiscal","Lançamento de ofício do tributo","Vencimento de obrigação acessória","Pedido de certidão negativa feito pelo devedor na repartição fiscal"],"explicacao":"Art. 174, parágrafo único, I, do CTN, com redação da LC 118/2005."},{"id":1833,"materia":"trib","nivel":3,"enunciado":"Pela regra geral do art. 173, I, do CTN, o prazo de decadência conta-se:","opcoes":["Do 1º dia do exercício seguinte àquele em que o lançamento poderia ser feito","Do dia em que ocorreu o fato gerador","Do dia da notificação do lançamento","Do vencimento do tributo"],"explicacao":"No lançamento por homologação sem dolo, fraude ou simulação, conta-se do fato gerador (art. 150, § 4º)."},{"id":1834,"materia":"trib","nivel":3,"enunciado":"No lançamento por homologação, sem dolo, fraude ou simulação, a decadência conta-se:","opcoes":["Da ocorrência do fato gerador","Do 1º dia do exercício seguinte","Da entrega da declaração","Da inscrição em dívida ativa"],"explicacao":"Art. 150, § 4º: passados 5 anos, ocorre a homologação tácita."},{"id":1835,"materia":"trib","nivel":3,"enunciado":"O ITCMD (heranças e doações) é de competência:","opcoes":["Dos estados e do DF","Dos municípios","Da União","Dos municípios e do DF"],"explicacao":"Art. 155, I, da CF."},{"id":1836,"materia":"trib","nivel":3,"enunciado":"O ITBI, sobre transmissão onerosa de imóveis entre vivos, é de competência:","opcoes":["Dos municípios","Dos estados","Da União","Dos estados e do DF"],"explicacao":"Art. 156, II, da CF."},{"id":1837,"materia":"trib","nivel":3,"enunciado":"A competência residual para criar novos impostos pertence:","opcoes":["À União, por lei complementar","Aos estados, por lei ordinária","À União, por medida provisória","Aos estados e municípios juntos"],"explicacao":"Art. 154, I: devem ser não cumulativos e ter fato gerador ou base diferente dos já previstos."},{"id":1838,"materia":"trib","nivel":3,"enunciado":"Quanto às anterioridades, o IPI é exceção:","opcoes":["Apenas à anterioridade anual","Apenas à nonagesimal","A ambas as anterioridades, anual e nonagesimal","A nenhuma anterioridade"],"explicacao":"O IPI respeita os 90 dias, mas não precisa esperar o exercício seguinte."},{"id":1839,"materia":"trib","nivel":3,"enunciado":"Pela Súmula Vinculante 50, a norma que apenas altera o prazo de recolhimento do tributo:","opcoes":["Não se sujeita ao princípio da anterioridade","Deve respeitar a anterioridade anual","Deve respeitar a anterioridade nonagesimal","Só pode ser feita por lei complementar"],"explicacao":"Mudar a data de vencimento não é criar nem aumentar tributo."},{"id":1840,"materia":"trib","nivel":3,"enunciado":"Pela Súmula Vinculante 29, é constitucional a taxa que adota:","opcoes":["Elementos da base de um imposto, sem identidade integral","A mesma base de cálculo de um imposto já existente no sistema","O valor venal do imóvel como base exclusiva","O faturamento da empresa como única base"],"explicacao":"O art. 145, § 2º, proíbe apenas base de cálculo própria de imposto."},{"id":1841,"materia":"afo","nivel":3,"enunciado":"Pela CF, o Plano Plurianual (PPA) vigora por:","opcoes":["4 anos, do 2º ano de um mandato ao 1º do seguinte","4 anos, coincidindo com o mandato","2 anos, renovável por igual período","1 ano, sendo renovado junto com a aprovação da LOA"],"explicacao":"ADCT, art. 35, § 2º, I."},{"id":1842,"materia":"afo","nivel":3,"enunciado":"O projeto do PPA da União deve ser enviado ao Congresso até:","opcoes":["31 de agosto do 1º ano do mandato","15 de abril de cada ano","31 de dezembro do 1º ano do mandato presidencial","30 de junho do último ano"],"explicacao":"E devolvido para sanção até o encerramento da sessão legislativa."},{"id":1843,"materia":"afo","nivel":3,"enunciado":"Pela CF, é vedado o início de programas ou projetos:","opcoes":["Não incluídos na lei orçamentária anual","Aprovados por decreto do Executivo","Financiados com receitas próprias do órgão","Previstos no Plano Plurianual vigente"],"explicacao":"Art. 167, I, da CF."},{"id":1844,"materia":"afo","nivel":3,"enunciado":"Autorizar créditos suplementares na própria LOA é exceção ao princípio da:","opcoes":["Exclusividade","Anualidade","Unidade","Universalidade"],"explicacao":"Art. 165, § 8º: também se admite autorizar operações de crédito, inclusive por ARO."},{"id":1845,"materia":"afo","nivel":3,"enunciado":"A transposição, o remanejamento e a transferência de recursos de uma categoria para outra dependem de:","opcoes":["Prévia autorização legislativa","Simples decreto do Executivo","Portaria do ministro da área","Parecer do Tribunal de Contas"],"explicacao":"Art. 167, VI, da CF."},{"id":1846,"materia":"afo","nivel":3,"enunciado":"Pela Lei 4.320/1964, pertencem ao exercício financeiro:","opcoes":["As receitas nele arrecadadas e as despesas nele empenhadas","As receitas nele lançadas e as despesas nele pagas","As receitas nele previstas e as despesas liquidadas","As receitas e as despesas efetivamente recebidas e pagas no ano civil"],"explicacao":"Art. 35: regime misto (caixa na receita, competência na despesa)."},{"id":1847,"materia":"afo","nivel":3,"enunciado":"Despesas de exercícios encerrados que não foram processadas na época própria são pagas como:","opcoes":["Despesas de exercícios anteriores","Restos a pagar não processados","Créditos extraordinários","Operações especiais"],"explicacao":"Art. 37 da Lei 4.320/1964."},{"id":1848,"materia":"afo","nivel":3,"enunciado":"Restos a pagar processados são despesas:","opcoes":["Empenhadas e liquidadas, mas não pagas","Empenhadas, mas ainda não liquidadas","Previstas, mas ainda não empenhadas","Pagas, mas ainda não contabilizadas no balanço patrimonial"],"explicacao":"Os não processados foram empenhados, mas não liquidados."},{"id":1849,"materia":"afo","nivel":3,"enunciado":"Pela LRF, a receita corrente líquida soma as receitas do mês de referência e dos:","opcoes":["11 meses anteriores","5 meses anteriores","23 meses anteriores","3 meses anteriores"],"explicacao":"Art. 2º, § 3º, da LRF."},{"id":1850,"materia":"afo","nivel":3,"enunciado":"Pela LRF, o limite de pessoal do Legislativo municipal, incluído o Tribunal de Contas, é de:","opcoes":["6% da RCL","3% da RCL","12% da RCL","2% da RCL"],"explicacao":"Art. 20, III, a."},{"id":1851,"materia":"afo","nivel":3,"enunciado":"Pela LRF, o limite de pessoal do Executivo estadual é de:","opcoes":["49% da RCL","54% da RCL","40,9% da RCL","60% da RCL"],"explicacao":"Art. 20, II, c."},{"id":1852,"materia":"afo","nivel":3,"enunciado":"Pela LRF, o Tribunal de Contas emite alerta quando a despesa com pessoal passa de:","opcoes":["90% do limite","95% do limite","80% do limite","100% do limite"],"explicacao":"Art. 59, § 1º, II. Acima de 95% é o limite prudencial."},{"id":1853,"materia":"afo","nivel":3,"enunciado":"Se a receita puder não comportar as metas fiscais, cada Poder deve, nos 30 dias após o bimestre, promover:","opcoes":["Limitação de empenho e de movimentação financeira","Abertura de créditos extraordinários","Aumento imediato de alíquotas","Contratação imediata de operação de crédito por antecipação de receita"],"explicacao":"Art. 9º da LRF."},{"id":1854,"materia":"afo","nivel":3,"enunciado":"Pela LRF, a limitação de empenho NÃO pode atingir:","opcoes":["Obrigações constitucionais e legais do ente","Despesas com publicidade institucional","Investimentos em obras novas ainda não iniciadas pelo ente","Diárias e passagens de servidores"],"explicacao":"Art. 9º, § 2º, da LRF."},{"id":1855,"materia":"afo","nivel":3,"enunciado":"Pela LRF, transferência voluntária é a entrega de recursos a outro ente:","opcoes":["A título de cooperação, sem decorrer da CF ou de lei","Por determinação da Constituição Federal","Para o SUS, por imposição legal","Como repartição obrigatória de receitas tributárias"],"explicacao":"Art. 25 da LRF."},{"id":1856,"materia":"afo","nivel":3,"enunciado":"A LRF proíbe a realização de operação de crédito entre:","opcoes":["Um ente da Federação e outro","A União e bancos privados nacionais","Estados e organismos internacionais","Municípios e instituições de fomento"],"explicacao":"Art. 35, inclusive por meio de fundos, autarquias, fundações ou estatais."},{"id":1857,"materia":"afo","nivel":3,"enunciado":"Na receita orçamentária, o estágio em que o contribuinte paga aos agentes arrecadadores é a:","opcoes":["Arrecadação","Previsão","Lançamento","Recolhimento"],"explicacao":"No recolhimento, os agentes repassam ao Tesouro."},{"id":1858,"materia":"afo","nivel":3,"enunciado":"Pela Lei 4.320/1964, o pagamento da despesa só pode ser feito após a:","opcoes":["Regular liquidação","Publicação da LOA","Aprovação do TCU","Emissão da nota fiscal"],"explicacao":"Art. 62 da Lei 4.320/1964."},{"id":1859,"materia":"gest","nivel":3,"enunciado":"Na matriz SWOT, forças e fraquezas são fatores:","opcoes":["Internos à organização","Externos à organização","Do macroambiente","Ligados à concorrência"],"explicacao":"Oportunidades e ameaças são externas."},{"id":1860,"materia":"gest","nivel":3,"enunciado":"A ferramenta 5W2H serve para:","opcoes":["Detalhar um plano de ação com perguntas-chave","Medir a satisfação dos clientes externos","Classificar problemas por gravidade e urgência","Ordenar as causas de um problema por frequência"],"explicacao":"What, why, where, when, who, how e how much."},{"id":1861,"materia":"gest","nivel":3,"enunciado":"Metas SMART devem ser específicas, mensuráveis, atingíveis, relevantes e:","opcoes":["Temporais","Simples","Motivadoras","Rentáveis"],"explicacao":"O T é de time-bound: com prazo definido."},{"id":1862,"materia":"gest","nivel":3,"enunciado":"Para Mintzberg, a estrutura típica de organizações de especialistas, como hospitais e universidades, é a:","opcoes":["Burocracia profissional","Estrutura simples","Adhocracia","Forma divisionalizada"],"explicacao":"O núcleo operacional é a parte-chave e a coordenação se dá pela padronização de habilidades."},{"id":1863,"materia":"gest","nivel":3,"enunciado":"Na teoria de Vroom, a crença de que o bom desempenho levará à recompensa chama-se:","opcoes":["Instrumentalidade","Valência","Expectância","Equidade"],"explicacao":"Valência é o valor dado à recompensa; expectância, a crença de que o esforço gera desempenho."},{"id":1864,"materia":"gest","nivel":3,"enunciado":"Pela teoria da equidade, de Adams, a motivação depende:","opcoes":["Da comparação entre a própria relação esforço/recompensa e a dos outros","Da satisfação das necessidades na ordem da pirâmide","Da definição de metas difíceis e específicas","Do reforço positivo dado logo após o comportamento desejado, como prega Skinner"],"explicacao":"Quem se sente injustiçado reduz o esforço ou busca compensação."},{"id":1865,"materia":"gest","nivel":3,"enunciado":"A teoria que defende metas específicas e desafiadoras como fonte de motivação é de:","opcoes":["Locke","Skinner","Adams","Argyris"],"explicacao":"Teoria do estabelecimento de metas (goal setting)."},{"id":1866,"materia":"gest","nivel":3,"enunciado":"O erro de avaliação em que uma característica marcante do avaliado contamina todas as demais é o:","opcoes":["Efeito halo","Erro de tendência central","Efeito recência","Erro de leniência"],"explicacao":"Também chamado de efeito auréola."},{"id":1867,"materia":"gest","nivel":3,"enunciado":"Na gestão pública, eficácia diz respeito a:","opcoes":["Alcançar os objetivos e as metas","Usar bem os recursos, com menor custo","Gerar impacto duradouro na sociedade","Cumprir rigorosamente os procedimentos"],"explicacao":"Eficiência é o uso dos recursos; efetividade, o impacto."},{"id":1868,"materia":"gest","nivel":3,"enunciado":"A teoria do reforço, que explica o comportamento pelas suas consequências, é de:","opcoes":["Skinner","Locke","Maslow","Vroom"],"explicacao":"Comportamentos reforçados tendem a se repetir."},{"id":1869,"materia":"gest","nivel":3,"enunciado":"O modelo patrimonialista de administração pública se caracteriza por:","opcoes":["Confusão entre patrimônio público e privado","Ênfase em resultados e no atendimento ao cidadão-cliente","Impessoalidade e regras formais rígidas","Contratos de gestão com metas"],"explicacao":"Nepotismo e corrupção são suas marcas."},{"id":1870,"materia":"gest","nivel":3,"enunciado":"No modelo gerencial, o controle prévio dos processos, típico da burocracia, dá lugar ao controle:","opcoes":["De resultados, a posteriori","Hierárquico e formal, a priori, de cada etapa","Social, apenas eleitoral","Judicial, prévio"],"explicacao":"Foco nos resultados e não nos procedimentos."},{"id":1871,"materia":"gest","nivel":3,"enunciado":"Pelo PDRAE de 1995, as atividades exclusivas do Estado, como fiscalização e regulação, ficariam com:","opcoes":["Agências executivas e reguladoras","Organizações sociais","Concessionárias privadas","Organizações da sociedade civil de interesse público"],"explicacao":"Os serviços não exclusivos iriam para organizações sociais."},{"id":1872,"materia":"gest","nivel":3,"enunciado":"Pelo PDRAE, os serviços não exclusivos do Estado, como hospitais e universidades, passariam a:","opcoes":["Organizações sociais, pela publicização","Agências reguladoras, pela regulação","Empresas estatais, pela estatização","Autarquias, pela descentralização"],"explicacao":"Publicização é a transferência ao setor público não estatal."},{"id":1873,"materia":"gest","nivel":3,"enunciado":"Pelo Decreto 9.203/2017, são princípios da governança pública, entre outros:","opcoes":["Capacidade de resposta, integridade e transparência","Lucratividade, competitividade e sigilo","Centralização, hierarquia e formalismo","Neutralidade, anonimato e discricionariedade ampla dos gestores"],"explicacao":"Também confiabilidade, melhoria regulatória e prestação de contas."},{"id":1874,"materia":"gest","nivel":3,"enunciado":"Na gestão de projetos, a restrição tripla clássica envolve escopo, prazo e:","opcoes":["Custo","Equipe","Risco","Fornecedores"],"explicacao":"Mudar um deles afeta os outros dois e a qualidade."},{"id":1875,"materia":"gest","nivel":3,"enunciado":"No ciclo de políticas públicas, a etapa inicial costuma ser a:","opcoes":["Formação da agenda","Avaliação dos resultados","Implementação","Tomada de decisão"],"explicacao":"Depois vêm formulação, decisão, implementação e avaliação."},{"id":1876,"materia":"gest","nivel":3,"enunciado":"O modelo das cinco forças de Porter analisa:","opcoes":["A competitividade de um setor","A motivação dos empregados","A estrutura hierárquica interna","O ciclo de vida do produto"],"explicacao":"Rivalidade, novos entrantes, substitutos e poder de clientes e fornecedores."},{"id":1877,"materia":"arq","nivel":3,"enunciado":"Pela Lei 8.159/1991, arquivos correntes são documentos:","opcoes":["Em curso ou de consulta frequente","De valor histórico e informativo","Que aguardam eliminação ou recolhimento ao permanente","Sem tratamento técnico"],"explicacao":"Art. 8º, § 1º."},{"id":1878,"materia":"arq","nivel":3,"enunciado":"Pela Lei 8.159/1991, arquivos intermediários são os que:","opcoes":["Aguardam eliminação ou recolhimento por interesse administrativo","Têm valor histórico e devem ser preservados para sempre","Estão em uso diário pelos setores produtores","Foram digitalizados e, por isso, já podem ser descartados sem avaliação"],"explicacao":"Art. 8º, § 2º."},{"id":1879,"materia":"arq","nivel":3,"enunciado":"O princípio da indivisibilidade (integridade) dos fundos determina que um fundo:","opcoes":["Não seja dispersado, mutilado ou alienado","Tenha cada documento em pasta própria","Seja ordenado sempre por assunto","Seja unido a fundos de outros órgãos"],"explicacao":"O fundo deve ser preservado sem dispersão."},{"id":1880,"materia":"arq","nivel":3,"enunciado":"O princípio da territorialidade determina que os arquivos:","opcoes":["Fiquem no território onde foram produzidos","Sejam guardados na capital federal","Sejam transferidos ao Arquivo Nacional","Acompanhem o servidor que os produziu quando ele for removido"],"explicacao":"Também chamado de princípio da pertinência territorial."},{"id":1881,"materia":"arq","nivel":3,"enunciado":"O princípio da cumulatividade indica que o arquivo se forma de modo:","opcoes":["Natural e progressivo","Artificial e por coleção","Periódico, a cada 5 anos","Seletivo, só com documentos históricos"],"explicacao":"O arquivo é sedimentação das atividades do órgão."},{"id":1882,"materia":"arq","nivel":3,"enunciado":"Uma coleção, diferentemente de um fundo, é:","opcoes":["Reunião artificial de documentos","Conjunto de mesma proveniência","Série de documentos de mesma função","Acervo orgânico de uma pessoa jurídica"],"explicacao":"Na coleção não há relação orgânica entre os documentos."},{"id":1883,"materia":"arq","nivel":3,"enunciado":"No método alfabético, “João Carlos de Souza” é ordenado como:","opcoes":["SOUZA, João Carlos de","DE SOUZA, João Carlos","CARLOS DE SOUZA, João","JOÃO CARLOS de Souza"],"explicacao":"Inverte-se pelo último sobrenome; artigos e preposições não são considerados."},{"id":1884,"materia":"arq","nivel":3,"enunciado":"No método alfabético, “Pedro Santos Filho” é ordenado como:","opcoes":["SANTOS FILHO, Pedro","FILHO, Pedro Santos","PEDRO Santos Filho","SANTOS, Pedro Filho"],"explicacao":"Filho, Júnior, Neto e Sobrinho acompanham o sobrenome, mas não são considerados na ordenação."},{"id":1885,"materia":"arq","nivel":3,"enunciado":"No método alfabético, nomes espanhóis são ordenados pelo:","opcoes":["Penúltimo sobrenome","Último sobrenome","Primeiro prenome","Segundo prenome"],"explicacao":"O penúltimo sobrenome é o de família do pai."},{"id":1886,"materia":"arq","nivel":3,"enunciado":"No método alfabético, nomes orientais (japoneses, chineses, árabes) são ordenados:","opcoes":["Como se apresentam, sem inversão","Pelo último nome, invertido","Pelo prenome cristão adotado","Pela nacionalidade do titular"],"explicacao":"É a regra das normas de alfabetação."},{"id":1887,"materia":"arq","nivel":3,"enunciado":"O método duplex de arquivamento é:","opcoes":["Numérico, com classes e subclasses por assunto","Alfabético, com cores diferentes para cada letra do sobrenome","Geográfico, por estado e cidade","Cronológico, por data de entrada"],"explicacao":"Parte do geral para o particular, como no decimal, mas sem limite de 10 classes."},{"id":1888,"materia":"arq","nivel":3,"enunciado":"O método decimal de Dewey divide o conhecimento em:","opcoes":["10 classes principais","5 classes principais","100 classes principais","26 classes, uma por letra"],"explicacao":"De 000 a 900, subdivididas de dez em dez."},{"id":1889,"materia":"arq","nivel":3,"enunciado":"Na tabela de temporalidade, a destinação “guarda permanente” significa que o documento:","opcoes":["Nunca poderá ser eliminado","Será eliminado após 100 anos","Será microfilmado e eliminado","Ficará no arquivo corrente"],"explicacao":"Documentos permanentes são inalienáveis e imprescritíveis."},{"id":1890,"materia":"arq","nivel":3,"enunciado":"A Comissão Permanente de Avaliação de Documentos tem como função principal:","opcoes":["Orientar e realizar a avaliação e seleção de documentos","Julgar servidores que extraviarem documentos","Autorizar sozinha eliminações, sem dar publicidade ao ato","Digitalizar todo o acervo do órgão"],"explicacao":"Decreto 4.073/2002, art. 18."},{"id":1891,"materia":"arq","nivel":3,"enunciado":"Antes de eliminar documentos públicos, o órgão deve publicar o:","opcoes":["Edital de ciência de eliminação","Termo de recolhimento","Termo de transferência","Guia de fundos"],"explicacao":"Previsto em resolução do CONARQ, dando prazo para manifestação de interessados."},{"id":1892,"materia":"arq","nivel":3,"enunciado":"O instrumento de pesquisa que descreve, de forma sumária ou analítica, as unidades de um fundo ou parte dele é o:","opcoes":["Inventário","Guia","Catálogo","Índice"],"explicacao":"O guia é mais geral; o catálogo descreve peça a peça."},{"id":1893,"materia":"arq","nivel":3,"enunciado":"Em arquivologia, o suporte é:","opcoes":["O material onde a informação é registrada","O conteúdo informativo do documento","O órgão que produziu o documento","A forma de organizar as séries"],"explicacao":"Papel, filme, disco e mídia digital são suportes."},{"id":1894,"materia":"arq","nivel":3,"enunciado":"Espécie documental é:","opcoes":["O formato do documento, como ata, ofício ou certidão","O material onde a informação está registrada","O conjunto de documentos de uma mesma função","O método usado para ordenar os documentos dentro das pastas suspensas"],"explicacao":"Tipo documental é a espécie somada à atividade: ata de reunião, certidão de nascimento."},{"id":1895,"materia":"civ","nivel":4,"enunciado":"Pela teoria menor da desconsideração, aplicada no CDC e no direito ambiental, basta:","opcoes":["O obstáculo ao ressarcimento dos prejuízos","Provar desvio de finalidade praticado com dolo","Provar confusão patrimonial entre sócio e empresa","Decisão prévia do juiz da falência da empresa"],"explicacao":"Art. 28, § 5º, do CDC. A teoria maior (art. 50 do CC) exige abuso."},{"id":1896,"materia":"civ","nivel":4,"enunciado":"A desconsideração inversa da personalidade jurídica atinge:","opcoes":["Bens da empresa por dívidas do sócio","Bens do sócio por dívidas da empresa","Bens de terceiros que contrataram com a empresa","Apenas bens públicos cedidos à empresa"],"explicacao":"Art. 50, § 3º, do Código Civil."},{"id":1897,"materia":"civ","nivel":4,"enunciado":"Pelo art. 1.829, o cônjuge NÃO concorre com os descendentes se era casado com o falecido no regime da:","opcoes":["Comunhão universal de bens","Separação convencional de bens","Participação final nos aquestos","Comunhão parcial, havendo bens particulares"],"explicacao":"Também não concorre na separação obrigatória ou na comunhão parcial sem bens particulares."},{"id":1898,"materia":"civ","nivel":4,"enunciado":"Concorrendo com descendentes que também são seus filhos, o cônjuge tem quinhão nunca inferior a:","opcoes":["1/4 da herança","1/3 da herança","1/2 da herança","1/5 da herança"],"explicacao":"Art. 1.832 do Código Civil."},{"id":1899,"materia":"civ","nivel":4,"enunciado":"O direito real de habitação do cônjuge sobrevivente (art. 1.831) recai sobre:","opcoes":["O imóvel residencial da família, se for o único a inventariar","Todos os imóveis do falecido, por toda a vida do cônjuge sobrevivente","Metade dos imóveis urbanos que compõem o espólio","O imóvel de maior valor do espólio, por 10 anos"],"explicacao":"Vale qualquer que seja o regime de bens."},{"id":1900,"materia":"civ","nivel":4,"enunciado":"Pelo art. 1.814, é excluído da sucessão por indignidade o herdeiro que:","opcoes":["For autor de homicídio doloso contra o autor da herança","Deixar de visitar o autor da herança na velhice","For condenado por qualquer crime culposo","Tiver renunciado antes a outra herança deixada por alguém da mesma família"],"explicacao":"Inclui a tentativa e o crime contra cônjuge, companheiro, ascendente ou descendente do autor da herança."},{"id":1901,"materia":"civ","nivel":4,"enunciado":"A renúncia à herança deve ser feita por:","opcoes":["Instrumento público ou termo judicial","Simples declaração verbal aos demais herdeiros","Carta registrada enviada ao inventariante","Escritura particular com duas testemunhas"],"explicacao":"Art. 1.806 do Código Civil."},{"id":1902,"materia":"civ","nivel":4,"enunciado":"A aceitação ou a renúncia da herança podem ser parciais ou sob condição?","opcoes":["Não, ambas são totais e incondicionais","Sim, ambas podem ser parciais","Só a aceitação pode ser parcial","Só a renúncia pode ser condicional ou a termo"],"explicacao":"Art. 1.808 do Código Civil."},{"id":1903,"materia":"civ","nivel":4,"enunciado":"A doação de ascendente a descendente importa:","opcoes":["Adiantamento do que lhe cabe por herança","Doação inoficiosa, nula de pleno direito","Renúncia tácita à herança futura do donatário","Exclusão dos demais herdeiros da sucessão"],"explicacao":"Art. 544. Por isso, o bem deve ser trazido à colação."},{"id":1904,"materia":"civ","nivel":4,"enunciado":"Doação inoficiosa é aquela que:","opcoes":["Excede o que o doador poderia dispor em testamento","É feita sem escritura pública registrada em cartório","Beneficia pessoa jurídica sem fins lucrativos","É feita ao cônjuge casado no regime de separação"],"explicacao":"Art. 549: é nula apenas na parte que exceder."},{"id":1905,"materia":"civ","nivel":4,"enunciado":"Além da ingratidão do donatário, a doação pode ser revogada por:","opcoes":["Inexecução do encargo","Arrependimento do doador","Casamento do donatário","Mudança de domicílio do doador"],"explicacao":"Art. 555 do Código Civil."},{"id":1906,"materia":"civ","nivel":4,"enunciado":"Salvo renúncia expressa, o fiador demandado tem o benefício de:","opcoes":["Ordem: primeiro se executam os bens do devedor","Ser liberado se o devedor mudar de endereço sem avisar o credor","Pagar apenas metade da dívida afiançada","Escolher qual credor receberá primeiro"],"explicacao":"Art. 827 do Código Civil."},{"id":1907,"materia":"civ","nivel":4,"enunciado":"Na compra e venda, salvo cláusula em contrário, as despesas de escritura e registro ficam a cargo do:","opcoes":["Comprador","Vendedor","Tabelião","Corretor"],"explicacao":"Art. 490. As da tradição ficam com o vendedor."},{"id":1908,"materia":"civ","nivel":4,"enunciado":"É anulável a venda de ascendente a descendente sem o consentimento:","opcoes":["Dos outros descendentes e do cônjuge do vendedor","Do tabelião e de duas testemunhas instrumentárias","Do Ministério Público e do juiz da vara de família","Apenas do descendente mais velho entre os demais"],"explicacao":"Art. 496. O consentimento do cônjuge é dispensado na separação obrigatória."},{"id":1909,"materia":"civ","nivel":4,"enunciado":"A cláusula de retrovenda permite ao vendedor de imóvel recomprá-lo no prazo máximo de:","opcoes":["3 anos","1 ano","5 anos","10 anos"],"explicacao":"Art. 505 do Código Civil."},{"id":1910,"materia":"civ","nivel":4,"enunciado":"A pretensão de ressarcimento por enriquecimento sem causa prescreve em:","opcoes":["3 anos","5 anos","10 anos","1 ano"],"explicacao":"Art. 206, § 3º, IV."},{"id":1911,"materia":"civ","nivel":4,"enunciado":"Em regra, a pretensão do segurado contra o segurador prescreve em:","opcoes":["1 ano","3 anos","5 anos","2 anos"],"explicacao":"Art. 206, § 1º, II, do Código Civil."},{"id":1912,"materia":"civ","nivel":4,"enunciado":"Pelos arts. 932 e 933, o empregador responde pelos atos dos empregados no exercício do trabalho:","opcoes":["Ainda que não haja culpa de sua parte","Somente se provada culpa na escolha do empregado","Apenas se o empregado não tiver bens próprios","Somente por danos materiais, nunca por danos morais"],"explicacao":"É responsabilidade objetiva por fato de terceiro."},{"id":1913,"materia":"pciv","nivel":4,"enunciado":"Pelo art. 489, § 1º, NÃO se considera fundamentada a decisão que:","opcoes":["Invoca precedente sem identificar seus fundamentos","Cita a lei e explica sua aplicação ao caso concreto","Enfrenta todos os argumentos capazes de infirmar a conclusão","Distingue o caso do precedente invocado pela parte"],"explicacao":"Também não é fundamentada a que usa conceitos indeterminados sem explicar o motivo."},{"id":1914,"materia":"pciv","nivel":4,"enunciado":"A técnica de ampliação do colegiado (art. 942) se aplica quando:","opcoes":["O julgamento da apelação não é unânime","A sentença é anulada monocraticamente pelo relator","O recurso é considerado intempestivo","Uma das partes pede sustentação oral"],"explicacao":"Novos julgadores são convocados para possibilitar a inversão do resultado."},{"id":1915,"materia":"pciv","nivel":4,"enunciado":"Em regra, os embargos de declaração:","opcoes":["Interrompem o prazo para outros recursos","Suspendem o prazo para outros recursos","Não afetam o prazo dos demais recursos cabíveis contra a decisão","Têm efeito suspensivo automático"],"explicacao":"Art. 1.026 do CPC."},{"id":1916,"materia":"pciv","nivel":4,"enunciado":"Embargos de declaração manifestamente protelatórios geram multa de até:","opcoes":["2% do valor atualizado da causa","10% do valor atualizado da causa","1% do valor total da condenação","20% do valor total da condenação"],"explicacao":"Art. 1.026, § 2º. Na reiteração, até 10%."},{"id":1917,"materia":"pciv","nivel":4,"enunciado":"A ação rescisória cabe, entre outros casos, quando a decisão de mérito:","opcoes":["Violar manifestamente norma jurídica","Divergir de entendimento posterior do STJ","Desagradar a parte que saiu vencida","For proferida por juiz substituto"],"explicacao":"Art. 966, V, do CPC."},{"id":1918,"materia":"pciv","nivel":4,"enunciado":"A reclamação (art. 988) pode ser usada, entre outros fins, para:","opcoes":["Garantir a observância de súmula vinculante","Rediscutir provas já examinadas pelo juiz","Substituir recurso que não foi interposto no prazo legal","Impugnar despacho de mero expediente"],"explicacao":"Também preserva a competência e a autoridade das decisões do tribunal."},{"id":1919,"materia":"pciv","nivel":4,"enunciado":"Pelo art. 332, o juiz julga liminarmente improcedente o pedido que contrariar, entre outros:","opcoes":["Súmula do STF ou do STJ","Parecer do Ministério Público","Doutrina majoritária do tema","Decisão de outro juiz de primeiro grau"],"explicacao":"Também acórdãos em recursos repetitivos e entendimentos em IRDR ou IAC."},{"id":1920,"materia":"pciv","nivel":4,"enunciado":"No cumprimento de sentença, o executado pode apresentar impugnação em:","opcoes":["15 dias após o fim do prazo para pagar voluntariamente","15 dias após a juntada do mandado de penhora","5 dias após ser intimado da sentença","30 dias após o trânsito em julgado da sentença"],"explicacao":"Art. 525, independentemente de penhora ou nova intimação."},{"id":1921,"materia":"pciv","nivel":4,"enunciado":"Na execução de alimentos pelo rito da prisão, o devedor pode ficar preso por:","opcoes":["1 a 3 meses, em regime fechado","6 meses a 1 ano, em regime semiaberto","Até 30 dias, em prisão domiciliar","Até 2 anos, em regime fechado"],"explicacao":"Art. 528, § 3º. A prisão não exime do pagamento."},{"id":1922,"materia":"pciv","nivel":4,"enunciado":"Pela Súmula 309 do STJ, a prisão civil por alimentos abrange:","opcoes":["As 3 parcelas anteriores à ação e as que vencerem no curso dela","Todo o débito acumulado desde a separação, sem qualquer limite de tempo","As 12 parcelas anteriores ao ajuizamento da execução","Apenas a última prestação vencida e não paga"],"explicacao":"Mesma regra do art. 528, § 7º, do CPC."},{"id":1923,"materia":"pciv","nivel":4,"enunciado":"Pelo art. 916, o executado de título extrajudicial pode depositar 30% e pagar o restante em até:","opcoes":["6 parcelas mensais","12 parcelas mensais","3 parcelas mensais","10 parcelas mensais"],"explicacao":"Com correção monetária e juros de 1% ao mês."},{"id":1924,"materia":"pciv","nivel":4,"enunciado":"A alienação de bem em fraude à execução é:","opcoes":["Ineficaz em relação ao exequente","Nula de pleno direito para todos","Anulável por meio de ação pauliana","Válida, cabendo apenas indenização"],"explicacao":"Art. 792, § 1º. A ação pauliana é para a fraude contra credores."},{"id":1925,"materia":"pciv","nivel":4,"enunciado":"Na execução, a penhora pode ser substituída por:","opcoes":["Fiança bancária ou seguro garantia, com acréscimo de 30%","Promessa escrita de pagamento futuro assinada pelo executado e testemunhas","Imóvel de terceiro, sem a anuência dele","Nota promissória emitida pelo próprio executado"],"explicacao":"Art. 835, § 2º, do CPC."},{"id":1926,"materia":"pciv","nivel":4,"enunciado":"O incidente de assunção de competência (IAC) cabe quando há questão de direito:","opcoes":["Relevante e de grande repercussão, sem repetição em massa","Repetida em milhares de processos que tramitam em vários estados","Exclusivamente constitucional, já julgada pelo STF","Já pacificada por súmula vinculante"],"explicacao":"Art. 947. Se houver repetição em massa, o caminho é o IRDR ou os repetitivos."},{"id":1927,"materia":"pciv","nivel":4,"enunciado":"Pela Lei 9.307/1996, a sentença arbitral:","opcoes":["Não fica sujeita a recurso nem a homologação judicial","Precisa ser homologada pelo juiz estadual competente antes da execução","Pode ser atacada por apelação ao tribunal de justiça","Só tem validade se confirmada depois pelo STJ"],"explicacao":"Art. 18. Ela é título executivo judicial."},{"id":1928,"materia":"pciv","nivel":4,"enunciado":"A cláusula de eleição de foro abusiva pode ser declarada ineficaz de ofício pelo juiz:","opcoes":["Antes da citação","Em qualquer tempo e grau","Somente após a contestação","Apenas pelo tribunal, em recurso"],"explicacao":"Art. 63, § 3º. Depois, cabe ao réu alegá-la na contestação."},{"id":1929,"materia":"pciv","nivel":4,"enunciado":"Pelo CPC, a desistência do recurso:","opcoes":["Independe da anuência do recorrido ou dos litisconsortes","Depende sempre do consentimento expresso do recorrido","Só pode ocorrer antes da distribuição ao relator","Exige homologação prévia do Ministério Público"],"explicacao":"Art. 998 do CPC."},{"id":1930,"materia":"pciv","nivel":4,"enunciado":"Pelo art. 1.022, cabem embargos de declaração contra qualquer decisão judicial para, entre outros fins:","opcoes":["Corrigir erro material","Reexaminar as provas dos autos","Rediscutir livremente o mérito","Anular a citação do réu"],"explicacao":"Também para esclarecer obscuridade, eliminar contradição e suprir omissão."},{"id":1931,"materia":"trib","nivel":4,"enunciado":"Pela EC 132/2023, o IBS é de competência:","opcoes":["Compartilhada entre estados, DF e municípios","Exclusiva da União","Exclusiva dos municípios","Exclusiva dos estados"],"explicacao":"A CBS é da União."},{"id":1932,"materia":"trib","nivel":4,"enunciado":"Pela EC 132/2023, o IBS e a CBS são cobrados, em regra, no:","opcoes":["Destino da operação","Local de origem do produto","Domicílio do fornecedor","Local da sede do fabricante"],"explicacao":"O princípio do destino reduz a guerra fiscal."},{"id":1933,"materia":"trib","nivel":4,"enunciado":"O órgão que administra o IBS de forma integrada é o:","opcoes":["Comitê Gestor do IBS","Conselho Nacional de Política Fazendária","Tribunal de Contas da União","Senado Federal, por resolução"],"explicacao":"Formado por representantes dos estados, do DF e dos municípios."},{"id":1934,"materia":"trib","nivel":4,"enunciado":"Pela EC 132/2023, a transição se completa com a extinção do ICMS e do ISS em:","opcoes":["2033","2027","2030","2026"],"explicacao":"A CBS entra plenamente em 2027; o IBS sobe gradualmente de 2029 a 2032."},{"id":1935,"materia":"trib","nivel":4,"enunciado":"Pelo art. 116, parágrafo único, do CTN, a autoridade pode desconsiderar atos praticados com a finalidade de:","opcoes":["Dissimular o fato gerador do tributo","Reduzir custos operacionais legítimos","Fazer planejamento previsto em lei","Pagar o tributo em parcelas"],"explicacao":"É a chamada norma geral antielisão."},{"id":1936,"materia":"trib","nivel":4,"enunciado":"Pela Súmula 436 do STJ, a declaração do contribuinte que reconhece débito fiscal:","opcoes":["Constitui o crédito, sem outra providência do fisco","Exige um lançamento de ofício posterior para ter validade jurídica","Apenas interrompe o prazo de decadência","Não tem efeito sem homologação expressa"],"explicacao":"O débito declarado e não pago pode ser inscrito em dívida ativa."},{"id":1937,"materia":"trib","nivel":4,"enunciado":"Pela Súmula 392 do STJ, a CDA pode ser substituída até a sentença dos embargos, mas não para:","opcoes":["Modificar o sujeito passivo da execução","Corrigir erro material de cálculo","Ajustar a data de vencimento","Incluir o número do processo administrativo"],"explicacao":"Erros materiais ou formais podem ser corrigidos."},{"id":1938,"materia":"trib","nivel":4,"enunciado":"A Súmula Vinculante 8 declarou inconstitucional o prazo de 10 anos de prescrição e decadência para:","opcoes":["Contribuições previdenciárias","Imposto de renda","ICMS","Taxas federais"],"explicacao":"Prescrição e decadência tributárias exigem lei complementar."},{"id":1939,"materia":"trib","nivel":4,"enunciado":"Pela Súmula Vinculante 24, o crime material contra a ordem tributária só se tipifica:","opcoes":["Após o lançamento definitivo do tributo","Com a simples entrega de declaração falsa","Após a inscrição do débito em dívida ativa","Com a citação na execução fiscal"],"explicacao":"Refere-se ao art. 1º, I a IV, da Lei 8.137/1990."},{"id":1940,"materia":"trib","nivel":4,"enunciado":"Pela Súmula Vinculante 21, é inconstitucional exigir depósito prévio para:","opcoes":["Admitir recurso administrativo","Propor a execução fiscal","Pedir parcelamento do débito","Emitir certidão positiva"],"explicacao":"Viola o direito de petição e o contraditório."},{"id":1941,"materia":"trib","nivel":4,"enunciado":"Pela CF, o ICMS:","opcoes":["Não incide sobre operações que destinem mercadorias ao exterior","Incide em dobro sobre as exportações de produtos industrializados e primários","Só incide sobre serviços de comunicação","É cobrado pela União nas importações"],"explicacao":"Art. 155, § 2º, X, a, assegurado o crédito das operações anteriores."},{"id":1942,"materia":"trib","nivel":4,"enunciado":"Pela CF, as alíquotas máximas e mínimas do ISS são fixadas por:","opcoes":["Lei complementar","Resolução do Senado","Lei ordinária municipal","Decreto do prefeito"],"explicacao":"Art. 156, § 3º, I. A LC 116/2003 fixa a máxima em 5%."},{"id":1943,"materia":"trib","nivel":4,"enunciado":"As alíquotas do ICMS nas operações interestaduais são estabelecidas por:","opcoes":["Resolução do Senado Federal","Lei complementar federal","Convênio do Confaz","Decreto do governador"],"explicacao":"Art. 155, § 2º, IV, da CF."},{"id":1944,"materia":"trib","nivel":4,"enunciado":"A progressividade do IPTU em razão do valor do imóvel passou a ser permitida com a:","opcoes":["EC 29/2000","CF de 1988, texto original","EC 42/2003","EC 132/2023"],"explicacao":"Súmula 668 do STF."},{"id":1945,"materia":"trib","nivel":4,"enunciado":"Salvo disposição em contrário, a isenção não se estende:","opcoes":["Às taxas e às contribuições de melhoria","Aos impostos de competência do ente","Aos tributos já lançados pelo fisco antes da lei isentiva","Aos fatos geradores futuros"],"explicacao":"Art. 177, I, do CTN."},{"id":1946,"materia":"trib","nivel":4,"enunciado":"Pelo art. 111 do CTN, interpreta-se literalmente a legislação que disponha sobre:","opcoes":["Outorga de isenção","Fato gerador de taxas","Base de cálculo do ICMS","Competência tributária"],"explicacao":"Também suspensão, exclusão do crédito e dispensa de obrigações acessórias."},{"id":1947,"materia":"trib","nivel":4,"enunciado":"Pelo art. 108, § 1º, do CTN, o emprego da analogia NÃO pode resultar em:","opcoes":["Exigência de tributo não previsto em lei","Interpretação de norma processual","Integração de lacuna da lei","Aplicação dos princípios gerais"],"explicacao":"É reflexo da legalidade tributária."},{"id":1948,"materia":"trib","nivel":4,"enunciado":"Pelo art. 123 do CTN, convenções particulares sobre responsabilidade pelo pagamento de tributos:","opcoes":["Não podem ser opostas à Fazenda Pública","Prevalecem sobre a lei tributária","Valem se registradas em cartório","Transferem a sujeição passiva ao comprador"],"explicacao":"Salvo disposição de lei em contrário."},{"id":1949,"materia":"afo","nivel":4,"enunciado":"Pela CF, as emendas de bancada estadual ao orçamento são de execução obrigatória até o limite de:","opcoes":["1% da RCL realizada no exercício anterior","2% da RCL do exercício corrente","0,5% da receita tributária líquida do ente federado no ano","5% da despesa primária total"],"explicacao":"Art. 166, § 12, incluído pela EC 100/2019."},{"id":1950,"materia":"afo","nivel":4,"enunciado":"Pela EC 126/2022, as emendas individuais ao orçamento ficam limitadas a:","opcoes":["2% da RCL do exercício anterior","1,2% da RCL do exercício anterior","5% da RCL do exercício corrente","0,5% da receita tributária"],"explicacao":"Art. 166, § 9º, da CF."},{"id":1951,"materia":"afo","nivel":4,"enunciado":"Metade do valor das emendas individuais deve ser destinada a:","opcoes":["Ações e serviços públicos de saúde","Manutenção da educação básica","Segurança pública e defesa civil","Obras de infraestrutura urbana"],"explicacao":"Art. 166, § 9º, da CF."},{"id":1952,"materia":"afo","nivel":4,"enunciado":"Pela LC 200/2023 (regime fiscal sustentável), o crescimento real da despesa primária fica limitado a:","opcoes":["Entre 0,6% e 2,5% ao ano","Até 5% ao ano","Zero, apenas a inflação","Entre 3% e 6% ao ano"],"explicacao":"Dentro dessa faixa, a despesa cresce conforme a receita."},{"id":1953,"materia":"afo","nivel":4,"enunciado":"Pela LC 200/2023, se a meta de resultado primário é cumprida, a despesa pode crescer, em termos reais, até:","opcoes":["70% do crescimento real da receita","50% do crescimento real da receita","100% do crescimento real da receita","30% do crescimento real da receita"],"explicacao":"Se a meta não é cumprida, o percentual cai para 50%."},{"id":1954,"materia":"afo","nivel":4,"enunciado":"As transferências especiais criadas pela EC 105/2019, apelidadas de “emendas Pix”, são repassadas:","opcoes":["Diretamente ao ente, sem convênio","Por convênio firmado com o ministério","Somente por meio de fundos setoriais","Após aprovação prévia do TCU"],"explicacao":"Art. 166-A da CF."},{"id":1955,"materia":"afo","nivel":4,"enunciado":"Pela LRF, empresa estatal dependente é a que:","opcoes":["Recebe do controlador recursos para pessoal ou custeio","Tem ações negociadas na bolsa de valores","Distribui lucros ao ente controlador todo ano, sem receber aportes","Atua em regime de concorrência no mercado"],"explicacao":"Art. 2º, III. Ela se submete aos limites da LRF."},{"id":1956,"materia":"afo","nivel":4,"enunciado":"Pela LRF, os recursos vinculados a finalidade específica devem ser usados:","opcoes":["Só nessa finalidade, ainda que em outro exercício","Em qualquer despesa, passados 6 meses","Para pagar a dívida pública, se sobrarem ao fim do exercício financeiro","Livremente a partir do exercício seguinte"],"explicacao":"Art. 8º, parágrafo único, da LRF."},{"id":1957,"materia":"afo","nivel":4,"enunciado":"Pela LRF, a dívida consolidada reúne as obrigações para amortização em prazo superior a:","opcoes":["12 meses","6 meses","24 meses","36 meses"],"explicacao":"Art. 29, I, da LRF."},{"id":1958,"materia":"afo","nivel":4,"enunciado":"Os limites da dívida consolidada de estados e municípios são fixados pelo:","opcoes":["Senado Federal","Congresso Nacional","Tribunal de Contas da União","Ministério da Fazenda"],"explicacao":"Art. 52, VI, da CF. Hoje, pela Resolução 40/2001."},{"id":1959,"materia":"afo","nivel":4,"enunciado":"Pela Resolução 40/2001 do Senado, a dívida consolidada líquida dos estados não pode passar de:","opcoes":["2 vezes a RCL","1,2 vez a RCL","3 vezes a RCL","50% da RCL"],"explicacao":"Para os municípios, o limite é de 1,2 vez a RCL."},{"id":1960,"materia":"afo","nivel":4,"enunciado":"Se um ente ultrapassar o limite da dívida consolidada, deve reconduzi-la em até:","opcoes":["3 quadrimestres, reduzindo ao menos 25% no primeiro","2 quadrimestres, reduzindo pelo menos 1/3 do excedente no primeiro","1 exercício inteiro, sem percentual mínimo","4 quadrimestres, reduzindo 50% no primeiro"],"explicacao":"Art. 31 da LRF."},{"id":1961,"materia":"afo","nivel":4,"enunciado":"Pela LRF, considera-se aumento de despesa obrigatória a prorrogação daquela criada por:","opcoes":["Prazo determinado","Lei complementar","Medida provisória","Decreto autônomo"],"explicacao":"Art. 17, § 7º, da LRF."},{"id":1962,"materia":"afo","nivel":4,"enunciado":"Pela LRF, NÃO entram no cálculo do limite de pessoal as despesas com:","opcoes":["Indenização por demissão de servidores","Proventos de inativos pagos pelo Tesouro","Encargos sociais recolhidos pelo ente","Terceirização que substitui servidores"],"explicacao":"Art. 19, § 1º. A terceirização substitutiva entra como “outras despesas de pessoal”."},{"id":1963,"materia":"afo","nivel":4,"enunciado":"Pela Lei 4.320/1964, o superávit financeiro apurado no balanço do ano anterior pode ser fonte para:","opcoes":["Abertura de créditos suplementares e especiais","Pagamento de despesas realizadas sem prévio empenho no exercício","Aumento automático do limite de pessoal","Criação de novos impostos pelo ente"],"explicacao":"Art. 43, § 1º, I."},{"id":1964,"materia":"afo","nivel":4,"enunciado":"Para abrir crédito suplementar ou especial, a Lei 4.320/1964 exige recursos disponíveis e:","opcoes":["Exposição que justifique a abertura","Parecer prévio favorável do Tribunal de Contas","Aprovação em plebiscito","Autorização do Banco Central"],"explicacao":"Art. 43 da Lei 4.320/1964."},{"id":1965,"materia":"afo","nivel":4,"enunciado":"Em regra, os créditos adicionais têm vigência:","opcoes":["Restrita ao exercício em que foram abertos","De 4 anos, junto com o PPA","Indeterminada, até se esgotarem os recursos que os financiam","De 2 anos, prorrogáveis"],"explicacao":"Art. 45. A exceção é a reabertura de especiais e extraordinários dos últimos 4 meses."},{"id":1966,"materia":"afo","nivel":4,"enunciado":"Pela CF, as disponibilidades de caixa da União (conta única do Tesouro) ficam depositadas no:","opcoes":["Banco Central do Brasil","Banco do Brasil","Caixa Econômica Federal","BNDES"],"explicacao":"Art. 164, § 3º. As de estados e municípios ficam em instituições financeiras oficiais."},{"id":1967,"materia":"gest","nivel":4,"enunciado":"Para Weber, a dominação baseada em regras impessoais e na legalidade é a:","opcoes":["Racional-legal","Carismática","Tradicional","Patrimonial"],"explicacao":"É a base do modelo burocrático."},{"id":1968,"materia":"gest","nivel":4,"enunciado":"Para Mintzberg, o principal mecanismo de coordenação da adhocracia é o:","opcoes":["Ajustamento mútuo","Supervisão direta","Padronização de processos","Padronização de resultados"],"explicacao":"A adhocracia é flexível e baseada em equipes de projeto."},{"id":1969,"materia":"gest","nivel":4,"enunciado":"A teoria dos dois fatores e a hierarquia de Maslow são classificadas como teorias:","opcoes":["De conteúdo","De processo","De reforço","Da contingência"],"explicacao":"Teorias de processo são, por exemplo, as de Vroom e Adams."},{"id":1970,"materia":"gest","nivel":4,"enunciado":"Na Teoria Z, William Ouchi propôs um modelo inspirado na gestão:","opcoes":["Japonesa","Norte-americana clássica","Soviética","Alemã"],"explicacao":"Emprego de longo prazo, decisão consensual e responsabilidade coletiva."},{"id":1971,"materia":"gest","nivel":4,"enunciado":"A teoria da liderança caminho-meta (path-goal) é de:","opcoes":["House","Fiedler","Likert","Tannenbaum"],"explicacao":"O líder esclarece o caminho para os liderados atingirem as metas."},{"id":1972,"materia":"gest","nivel":4,"enunciado":"No modelo de Fiedler, a eficácia da liderança depende do ajuste entre o estilo do líder e:","opcoes":["A favorabilidade da situação","A maturidade dos liderados","O tamanho da organização","O grau de centralização"],"explicacao":"Fiedler considera o estilo do líder relativamente fixo."},{"id":1973,"materia":"gest","nivel":4,"enunciado":"Os quatro sistemas de administração, do autoritário-coercitivo ao participativo, são de:","opcoes":["Likert","McGregor","Argyris","Barnard"],"explicacao":"Sistema 1 a Sistema 4."},{"id":1974,"materia":"gest","nivel":4,"enunciado":"No Balanced Scorecard, o mapa estratégico serve para:","opcoes":["Mostrar as relações de causa e efeito entre os objetivos","Listar apenas os indicadores financeiros do ano","Descrever o organograma, as chefias e as linhas de autoridade da organização","Registrar as reclamações recebidas dos clientes"],"explicacao":"Liga as quatro perspectivas numa lógica de causa e efeito."},{"id":1975,"materia":"gest","nivel":4,"enunciado":"No modelo de Greiner, cada fase de crescimento da organização termina em uma:","opcoes":["Crise que exige mudança de gestão","Fusão com outra organização","Redução obrigatória de pessoal","Abertura de capital na bolsa"],"explicacao":"Evolução e revolução se alternam."},{"id":1976,"materia":"gest","nivel":4,"enunciado":"No modelo de oito etapas de Kotter para a mudança, a primeira é:","opcoes":["Criar senso de urgência","Ancorar a mudança na cultura","Gerar vitórias de curto prazo","Formar a coalizão administrativa"],"explicacao":"A ancoragem na cultura é a última etapa."},{"id":1977,"materia":"gest","nivel":4,"enunciado":"Para Kurt Lewin, o processo de mudança organizacional passa por:","opcoes":["Descongelamento, mudança e recongelamento","Planejamento, execução e controle","Diagnóstico, intervenção e avaliação","Resistência, adaptação e aceitação"],"explicacao":"Também propôs a análise do campo de forças."},{"id":1978,"materia":"gest","nivel":4,"enunciado":"No modelo de Schein, os pressupostos básicos são o nível da cultura organizacional:","opcoes":["Mais profundo e inconsciente","Mais visível, como roupas e rituais","Dos valores declarados em documentos","Dos símbolos e da arquitetura"],"explicacao":"Os níveis são artefatos, valores declarados e pressupostos básicos."},{"id":1979,"materia":"gest","nivel":4,"enunciado":"A administração por objetivos (APO) foi popularizada por:","opcoes":["Peter Drucker","Henri Fayol","Elton Mayo","Max Weber"],"explicacao":"Objetivos definidos em conjunto entre chefe e subordinado."},{"id":1980,"materia":"gest","nivel":4,"enunciado":"O Novo Serviço Público, de Denhardt, critica a Nova Gestão Pública por tratar o cidadão como:","opcoes":["Cliente, e não como cidadão","Eleitor, e não como contribuinte","Servidor, e não como usuário","Acionista, e não como sócio"],"explicacao":"Propõe servir em vez de dirigir."},{"id":1981,"materia":"gest","nivel":4,"enunciado":"Pela Lei 13.460/2017, a pesquisa de satisfação para avaliar os serviços públicos deve ser feita, no mínimo:","opcoes":["A cada 1 ano","A cada mês","A cada 4 anos","A cada 6 meses"],"explicacao":"Art. 23, § 1º."},{"id":1982,"materia":"gest","nivel":4,"enunciado":"Pela Lei 14.129/2021 (Governo Digital), o número suficiente para identificar o cidadão nos bancos de dados públicos é o:","opcoes":["CPF","RG","Título de eleitor","NIS"],"explicacao":"Art. 9º da Lei 14.129/2021."},{"id":1983,"materia":"gest","nivel":4,"enunciado":"A análise de cenários prospectivos e a análise PEST fazem parte da etapa de:","opcoes":["Diagnóstico estratégico","Execução operacional","Controle orçamentário","Avaliação de desempenho individual"],"explicacao":"Servem para entender o ambiente externo."},{"id":1984,"materia":"gest","nivel":4,"enunciado":"O OKR (Objectives and Key Results) é um método de:","opcoes":["Definição e acompanhamento de metas","Avaliação de riscos financeiros","Recrutamento e seleção de pessoal","Controle de estoques e compras"],"explicacao":"Objetivos qualitativos com resultados-chave mensuráveis."},{"id":1985,"materia":"arq","nivel":4,"enunciado":"A norma brasileira de descrição arquivística é a:","opcoes":["NOBRADE","ISAD(G) Brasil","e-ARQ Brasil","NBR 6023"],"explicacao":"Aprovada pelo CONARQ em 2006, adaptando a ISAD(G)."},{"id":1986,"materia":"arq","nivel":4,"enunciado":"Quantos níveis principais de descrição a NOBRADE prevê, do acervo da entidade ao item documental?","opcoes":["6","3","4","10"],"explicacao":"Níveis 0 a 5: acervo, fundo ou coleção, seção, série, dossiê ou processo, e item."},{"id":1987,"materia":"arq","nivel":4,"enunciado":"A norma internacional geral de descrição arquivística é a:","opcoes":["ISAD(G)","ISO 9001","ISAAR(CPF)","ISDF"],"explicacao":"Publicada pelo Conselho Internacional de Arquivos."},{"id":1988,"materia":"arq","nivel":4,"enunciado":"A ISAAR(CPF) trata de registros de autoridade de:","opcoes":["Entidades coletivas, pessoas e famílias","Fundos e coleções de valor permanente","Funções e atividades exercidas pelos órgãos produtores","Instituições que custodiam acervos"],"explicacao":"CPF: Corporate bodies, Persons, Families."},{"id":1989,"materia":"arq","nivel":4,"enunciado":"O RDC-Arq (repositório arquivístico digital confiável) é recomendado pelo CONARQ para:","opcoes":["Custodiar e preservar documentos digitais a longo prazo","Digitalizar documentos produzidos em papel","Classificar informações sigilosas em graus de sigilo, conforme a LAI","Produzir documentos já em meio digital"],"explicacao":"Vale para as fases intermediária e permanente."},{"id":1990,"materia":"arq","nivel":4,"enunciado":"Pelo Decreto 10.278/2020, o documento digitalizado conforme suas regras:","opcoes":["Produz os mesmos efeitos legais do original","Só vale após autenticação em cartório","Nunca pode substituir o original em papel","Vale apenas como cópia simples, sem qualquer valor de prova"],"explicacao":"Desde que atendidos os requisitos de integridade, confiabilidade e metadados."},{"id":1991,"materia":"arq","nivel":4,"enunciado":"Pelo Decreto 10.278/2020, documentos digitalizados por órgãos públicos devem ser assinados com certificado digital:","opcoes":["ICP-Brasil","Emitido pelo próprio órgão","Do fabricante do scanner","Da Receita Federal"],"explicacao":"Garante autoria, integridade e validade jurídica."},{"id":1992,"materia":"arq","nivel":4,"enunciado":"Pela LAI, pode classificar informação como ultrassecreta no Executivo federal, entre outros:","opcoes":["O Presidente da República","O diretor de cada departamento","Qualquer servidor efetivo","O chefe do setor de protocolo"],"explicacao":"Também o Vice-Presidente, ministros e comandantes das Forças Armadas."},{"id":1993,"materia":"arq","nivel":4,"enunciado":"Pela LAI, o interessado pode recorrer da negativa de acesso no prazo de:","opcoes":["10 dias","5 dias","20 dias","30 dias"],"explicacao":"Art. 15 da Lei 12.527/2011."},{"id":1994,"materia":"arq","nivel":4,"enunciado":"Pela LAI, o recurso contra a negativa de acesso é dirigido à autoridade:","opcoes":["Superior à que negou o pedido","Que negou, para que reconsidere a própria decisão","Do Tribunal de Contas","Do Ministério Público"],"explicacao":"Ela deve se manifestar em 5 dias."},{"id":1995,"materia":"arq","nivel":4,"enunciado":"Em arquivologia, dossiê é:","opcoes":["Conjunto de documentos sobre uma mesma pessoa ou ação","Documento avulso, sem relação com outros","Instrumento de pesquisa mais geral do arquivo permanente","Caixa-arquivo onde se guardam os papéis"],"explicacao":"É uma unidade documental, como o processo."},{"id":1996,"materia":"arq","nivel":4,"enunciado":"No arranjo, a série documental é:","opcoes":["Sequência de documentos do mesmo tipo e da mesma função","Conjunto de fundos produzidos por vários órgãos","Coleção artificial de documentos raros e antigos reunidos pelo arquivista","Primeira subdivisão de um fundo arquivístico"],"explicacao":"A primeira subdivisão do fundo é a seção."},{"id":1997,"materia":"arq","nivel":4,"enunciado":"No arranjo, a seção corresponde:","opcoes":["À primeira subdivisão do fundo","Ao conjunto de documentos de um tipo","A um único documento do acervo","Ao conjunto de todos os fundos"],"explicacao":"Geralmente reflete as unidades administrativas do órgão."},{"id":1998,"materia":"arq","nivel":4,"enunciado":"A diplomática estuda:","opcoes":["A estrutura formal e a autenticidade dos documentos","A conservação física do papel e das tintas","A história dos arquivos nacionais e públicos desde a Idade Média","Os métodos de arquivamento alfabético"],"explicacao":"É disciplina auxiliar da arquivologia."},{"id":1999,"materia":"arq","nivel":4,"enunciado":"Para conservar documentos em papel, recomenda-se umidade relativa do ar de aproximadamente:","opcoes":["45% a 55%","70% a 80%","10% a 20%","85% a 95%"],"explicacao":"Com temperatura em torno de 20 °C e poucas oscilações."},{"id":2000,"materia":"arq","nivel":4,"enunciado":"A laminação e o reforço de folhas danificadas são medidas de:","opcoes":["Restauração","Avaliação","Classificação","Descrição"],"explicacao":"Visam recuperar documentos já deteriorados."},{"id":2001,"materia":"arq","nivel":4,"enunciado":"Pela Lei 8.159/1991, os documentos de valor permanente de órgãos públicos extintos devem ser:","opcoes":["Recolhidos à instituição arquivística pública","Eliminados depois de feito um inventário","Vendidos em leilão público","Entregues aos ex-servidores e dirigentes do órgão extinto"],"explicacao":"Art. 7º, § 2º."},{"id":2002,"materia":"arq","nivel":4,"enunciado":"O documento de arquivo se distingue do documento de biblioteca porque é produzido:","opcoes":["Organicamente, em razão das atividades de uma entidade","Para fins culturais e de divulgação ampla ao público","Em várias cópias idênticas, para venda ou distribuição","Por compra ou doação de terceiros à instituição"],"explicacao":"Arquivos são orgânicos; bibliotecas reúnem coleções."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

-- novas questões inseridas depois recebem números a partir daqui
select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select count(*) as total_de_questoes from public.questoes;
